import 'dotenv/config';
import { PrismaClient } from '@prisma/client';

const prisma = new PrismaClient();

const cultureData: Record<string, Array<{ topic: string; title: string; body: string; contextNote?: string }>> = {
  'amsterdam-netherlands': [
    { topic: 'ETIQUETTE', title: 'Cycling hierarchy', body: 'Cyclists have right of way over pedestrians almost everywhere in Amsterdam. Never step into a bike lane without looking — they are separated from car traffic and can be easy to miss. Bells are warnings, not greetings.', contextNote: 'Red-painted lanes are for bikes, grey is for pedestrians' },
    { topic: 'FOOD', title: 'Brown café culture', body: 'The traditional "bruin café" (brown café) is the Dutch pub: cosy, dimly lit, often with sawdust on the floor. Order beer (pils) or jenever (Dutch gin) and snack on bitterballen (fried meat ragout balls). Meals here are hearty and unfussy.', contextNote: 'Bruin cafés open from late morning and double as lunch spots' },
    { topic: 'MONEY', title: 'Card payments are standard', body: 'The Netherlands is highly cashless. Almost every shop, café, and market stall accepts debit card via PIN (Maestro/V Pay). Some places actively refuse cash. Carry a chip-and-PIN card; contactless works at most terminals too.', contextNote: 'ATMs are available but rarely needed' },
    { topic: 'TRANSPORT', title: 'OV-chipkaart for transit', body: 'Public transport (tram, metro, bus, train) uses the OV-chipkaart smart card. Buy an anonymous card at GVB booths or ticket machines. Always check in AND check out or you will be charged the maximum fare.', contextNote: 'Day passes are cheaper for tourists doing multiple rides' },
    { topic: 'LANGUAGE', title: 'Dutch and English co-exist', body: 'Nearly every Amsterdammer under 50 speaks excellent English, often switching before you even try Dutch. Learning a few phrases — "Dank je wel" (thank you) and "Alstublieft" (please/here you go) — is appreciated but not expected.', contextNote: '"Alstublieft" is used both when giving and receiving' },
    { topic: 'SAFETY', title: 'Tourist pickpocket zones', body: 'The Red Light District, Leidseplein, and Rembrandtplein are prime pickpocket areas, especially at night. Use a money belt or front pocket. Be cautious around Centraal Station and on crowded trams.', contextNote: 'Most crime is opportunistic, not violent' },
    { topic: 'DRESS', title: 'Casual is the norm', body: 'Amsterdam is relaxed and stylish but never stuffy. Smart-casual covers almost every venue — overly formal attire stands out. Pack layers for unpredictable rain; a waterproof jacket is more useful than an umbrella on a bike.', contextNote: 'Upscale restaurants may expect neat dress' },
  ],

  'austin-usa': [
    { topic: 'FOOD', title: 'BBQ is a religion', body: 'Central Texas BBQ means brisket, ribs, and sausage served on butcher paper with no sauce — the meat speaks for itself. The best pits (Franklin, La Barbecue, Micklethwait) often sell out before noon. Arrive early or expect to queue for an hour.', contextNote: 'Sauce on the side is available; asking for it is fine' },
    { topic: 'ETIQUETTE', title: 'Live music venues and tipping', body: 'On 6th Street and in venues across Austin, live bands often play for tips from a jar rather than a wage. It is considered good form to tip a dollar or two per song if you enjoy the set, especially in smaller bars.', contextNote: '"Keep Austin Weird" is the city\'s unofficial motto — embrace eccentricity' },
    { topic: 'TRANSPORT', title: 'Car culture dominates', body: 'Austin is a car city. Public transit (CapMetro buses and a limited rail line) exists but is slow and infrequent outside the core. Ride-shares (Uber/Lyft) are plentiful but surge during SXSW and ACL festival weekends.', contextNote: 'Parking downtown fills quickly during events' },
    { topic: 'MONEY', title: 'Tipping expectations', body: 'Standard US tipping applies: 18–20% at sit-down restaurants, $1–2 per drink at bars, 15–20% for ride-shares. Many coffee shops and counter-service spots now show tip prompts on tablets — 0% is an option but staff notice.', contextNote: 'Tax is added at checkout, not shown on menu prices' },
    { topic: 'SAFETY', title: 'Heat and sun in summer', body: 'Austin summers routinely exceed 100°F (38°C) with high humidity. Drink water constantly, wear sunscreen, and schedule outdoor activities for early morning or evening. Barton Springs Pool is a popular cool-down spot.', contextNote: 'Stay hydrated at outdoor festivals — heat exhaustion is common' },
    { topic: 'LANGUAGE', title: 'Southern hospitality is genuine', body: 'Austinites are friendly and will chat with strangers at bars, food trucks, and parks. "Y\'all" is universal — gender-neutral and warm. If someone asks "How are you?" as a greeting, a brief "Great, thanks!" is all that\'s expected.', contextNote: 'Texan pride is real; asking about Texas vs. the rest of the US can spark a conversation' },
  ],

  'bali-indonesia': [
    { topic: 'ETIQUETTE', title: 'Temple dress code', body: 'A sarong and sash are required to enter any Balinese Hindu temple. They are usually provided or can be rented at the entrance for a small fee. Shoulders should be covered; avoid wearing black (a funeral colour) during temple visits.', contextNote: 'Menstruating women are respectfully asked not to enter temples' },
    { topic: 'FOOD', title: 'Warung dining', body: 'A warung is a small family-run restaurant serving cheap, authentic Indonesian food. Nasi campur (mixed rice), satay, and gado-gado are staples. Avoid eating from warungs that look unclean — go where locals eat and food turns over quickly.', contextNote: 'Street food hygiene varies; ice from sealed bags is safer than tap-water ice' },
    { topic: 'DRESS', title: 'Modest dress outside tourist areas', body: 'Outside Kuta and Seminyak, Bali is culturally conservative. Cover knees and shoulders in villages and markets. Wearing a bikini top through a market or temple complex is considered disrespectful by locals.', contextNote: 'Ubud is stricter than beach towns — dress accordingly' },
    { topic: 'MONEY', title: 'Bargaining in markets', body: 'Haggling is expected at art markets (Sukawati, Ubud market) — open at around 40% of the asking price and work up. Fixed-price shops and restaurants do not expect negotiation. Never be aggressive; keep bargaining light and friendly.', contextNote: 'Only bargain if you genuinely intend to buy' },
    { topic: 'TRANSPORT', title: 'Scooter rental and traffic', body: 'Renting a scooter is common but traffic is chaotic and roads can be narrow and potholed. An International Driving Permit is technically required. Hire a local driver for day trips — rates are negotiable and far safer for first-time visitors.', contextNote: 'Traffic in Seminyak and Kuta at rush hour can add an hour to any journey' },
    { topic: 'LANGUAGE', title: 'Greeting in Balinese', body: '"Om Swastiastu" is the traditional Balinese Hindu greeting, used before entering temples or speaking to priests. For everyday use, Indonesian "Selamat pagi/siang/sore" (good morning/afternoon/evening) is warmly received. "Terima kasih" means thank you.', contextNote: 'Balinese is distinct from Indonesian — locals use both' },
    { topic: 'SAFETY', title: 'Monkey Forest caution', body: 'The Ubud Sacred Monkey Forest is popular but monkeys are wild and will grab bags, sunglasses, and food. Hold belongings tightly and do not make eye contact or bare teeth — they read this as aggression. Staff are on hand to assist.', contextNote: 'Do not carry obvious food items — monkeys are clever' },
  ],

  'bangkok-thailand': [
    { topic: 'ETIQUETTE', title: 'The wai greeting', body: 'The wai — pressing palms together at chest level and bowing the head — is Thailand\'s traditional greeting. Foreigners are not expected to initiate it but returning one is polite. The higher the hands and deeper the bow, the greater the respect shown.', contextNote: 'Never wai to a child or service worker; they should wai first' },
    { topic: 'FOOD', title: 'Street food safety', body: 'Bangkok\'s street food is world-class and generally safe if you follow locals\' cues. Look for carts with high turnover and freshly cooked food. Avoid raw salads and pre-cut fruit if your stomach is sensitive. Pad thai, som tam, and boat noodles are excellent starting points.', contextNote: 'Michelin has awarded several Bangkok street stalls stars' },
    { topic: 'DRESS', title: 'Temple dress requirements', body: 'At Wat Pho, Wat Arun, and especially the Grand Palace, shorts and sleeveless tops are not permitted. The Grand Palace has the strictest enforcement and provides sarongs for rent. Wear light, loose-fitting clothing that covers knees and shoulders.', contextNote: 'Carry a light scarf to cover up quickly at unexpected temple stops' },
    { topic: 'MONEY', title: 'Cash economy', body: 'Despite being a modern city, Bangkok remains heavily cash-based. Card acceptance is common in malls and hotels but rare at street stalls, markets, and local restaurants. Withdraw Thai Baht from ATMs (a 220 THB fee applies at most Bangkok ATMs); exchange rates at Superrich counters beat airport rates significantly.', contextNote: 'Never exchange money on the street — rates are manipulative' },
    { topic: 'TRANSPORT', title: 'BTS Skytrain and tuk-tuks', body: 'The BTS Skytrain and MRT metro are fast, air-conditioned, and cheap. Tuk-tuks are fun but overpriced for tourists — always agree on a price before getting in. Metered taxis are reliable; ensure the meter is switched on when you board.', contextNote: 'Tuk-tuk drivers near tourist sites often receive commissions from gem shops — decline detour offers' },
    { topic: 'SAFETY', title: 'Gem scam awareness', body: 'The "gem scam" is Bangkok\'s most notorious tourist con. A friendly stranger leads you to a "government gem sale" where you buy worthless stones at inflated prices. If someone approaches you unprompted with a great deal, politely decline and walk away.', contextNote: 'Other variants include the "closed today" temple scam' },
    { topic: 'LANGUAGE', title: 'Politeness particles', body: 'Thai speech uses polite particles: men say "Khrap" (ครับ) and women say "Ka" (ค่ะ) at the end of sentences to show respect. Even saying "Khob khun khrap/ka" (thank you) with the correct particle is greatly appreciated by locals.', contextNote: 'Thai is tonal; mispronunciation can change meaning entirely' },
  ],

  'barcelona-spain': [
    { topic: 'ETIQUETTE', title: 'Greeting with two kisses', body: 'The standard greeting between friends and when meeting new people socially is two kisses on the cheeks — right cheek first. This applies between women and between men and women; men typically handshake between themselves. Never offer a hug unless you know the person well.', contextNote: 'In professional settings, a handshake is safer' },
    { topic: 'FOOD', title: 'Eating schedules', body: 'Barcelona eats late — lunch runs 2–4pm and is the main meal of the day, dinner is rarely before 9pm. Many restaurants do not open for dinner until 8:30pm. The menú del día (set lunch menu) offers three courses for €12–15 and is the best-value meal in the city.', contextNote: 'Kitchens often close between 4–8pm; plan your meal times' },
    { topic: 'LANGUAGE', title: 'Catalan vs Spanish', body: 'Barcelona is in Catalonia, where Catalan (not Castilian Spanish) is the first language. Street signs, menus, and many conversations are in Catalan. Attempting a word or two in Catalan ("Gràcies" for thank you, "Bon dia" for good morning) is warmly received by locals.', contextNote: 'Everyone understands Spanish; using English is fine in most tourist contexts' },
    { topic: 'DRESS', title: 'Beach-to-street rules', body: 'Swimwear and bare torsos are only acceptable on the beach and boardwalk. Walking into the Gothic Quarter or Las Ramblas in a bikini is technically illegal under city bylaws and can result in a fine. Throw on a cover-up when leaving the beach zone.', contextNote: 'Anti-tourist sentiment is real in some neighbourhoods — dress respectfully' },
    { topic: 'MONEY', title: 'Tipping is modest', body: 'Tipping is appreciated but not compulsory in Barcelona. Rounding up the bill or leaving €1–2 on a café table is standard. At restaurants, 5–10% is generous. Service is included in prices by law, so a tip is a genuine bonus, not an obligation.', contextNote: 'Never tip more than 10% — it can seem condescending' },
    { topic: 'SAFETY', title: 'Las Ramblas pickpockets', body: 'Las Ramblas is one of Europe\'s most notorious pickpocket zones. Use a crossbody bag with a zip and keep your phone in a front pocket. Be especially vigilant at the Boqueria Market and crowded subway stations like Universitat and Passeig de Gràcia.', contextNote: 'Distraction thefts (spill, card trick, ask for directions) are common' },
    { topic: 'TRANSPORT', title: 'T-Casual metro card', body: 'The T-Casual (formerly T-10) card gives 10 metro/bus/tram rides at a discount — buy it at any metro ticket machine. The metro covers all major tourist sights. Avoid unlicensed taxis; Cabify and official cabs (black with yellow stripe) are safe alternatives.', contextNote: 'The airport bus (Aerobús) is cheaper than a taxi from El Prat' },
  ],

  'boston-usa': [
    { topic: 'ETIQUETTE', title: 'Direct and no-nonsense', body: 'Bostonians are famously direct — polite but blunt. Don\'t be put off by a terse response; it\'s not rudeness, it\'s efficiency. Small talk is less expected than in the South; locals will help if asked but won\'t initiate conversation unnecessarily.', contextNote: 'Sports (particularly Red Sox and Patriots) is the universal ice-breaker' },
    { topic: 'FOOD', title: 'Chowder and seafood culture', body: 'New England clam chowder (cream-based, never tomato) is the defining dish. Order it at Yankee Lobster or Legal Sea Foods on a Friday — Catholics avoiding meat made it a tradition that stuck. Lobster rolls are served either warm with butter or cold with mayo, depending on the place.', contextNote: '"Chowdah" is the local pronunciation — saying it right earns points' },
    { topic: 'TRANSPORT', title: 'The T: Boston\'s subway', body: 'The MBTA (called "the T") runs four colour-coded lines covering most tourist areas. Buy a CharlieCard for reusable travel (cheaper per ride than paper tickets). The Red and Green lines cover Harvard, Fenway, and downtown. Service stops around 12:30am.', contextNote: 'Green Line trolleys surface above-ground in some sections — exits can be confusing' },
    { topic: 'LANGUAGE', title: 'Boston accent and slang', body: 'The Boston accent drops the letter R after vowels — "park the car in Harvard Yard" sounds like "pahk the cah." "Wicked" means very ("wicked good" = really good). Locals say "Dunks" for Dunkin\' Donuts, which is taken seriously as a cultural institution.', contextNote: '"The Cape" refers to Cape Cod; "The Vineyard" means Martha\'s Vineyard' },
    { topic: 'MONEY', title: 'Tipping in line with US norms', body: 'Standard US tipping applies: 18–20% at restaurants, $1–2 per drink at bars. Boston has a higher cost of living than most US cities — budget accordingly for accommodation and dining, particularly near Beacon Hill and Back Bay.', contextNote: 'Uber surge pricing is common during Sox games and rush hour' },
    { topic: 'SAFETY', title: 'Walking city with caveats', body: 'Boston is very walkable and generally safe for tourists. After dark, Roxbury and parts of Dorchester are higher-crime areas best avoided unless you know the neighbourhood. The Freedom Trail is safe even at night in the tourist core.', contextNote: 'Drivers are aggressive — jaywalking is common but watch for cars regardless' },
  ],

  'cape-town-south-africa': [
    { topic: 'ETIQUETTE', title: 'Greeting culture', body: 'South Africans greet warmly and expect a handshake even among casual acquaintances. In Xhosa communities, a three-part handshake (regular, then thumbs interlock, then regular again) is common. Take time to ask "How are you?" and mean it.', contextNote: '"Howzit" is the universal informal greeting' },
    { topic: 'FOOD', title: 'Braai is sacred', body: 'A braai (barbecue) is a cornerstone of Cape Town social life — it is never just cooking, it is an event. Boerewors (spiced sausage), lamb chops, and sosaties (kebabs) are staples. If invited to a braai, bringing drinks and a dessert is expected.', contextNote: 'Offering to help with the braai is polite; taking over is not' },
    { topic: 'MONEY', title: 'Cash and tipping', body: 'The South African Rand is affordable for most visitors. Tipping is essential — waitstaff rely on it, and 10–15% is the norm. Tip your parking attendant (R5–10), petrol station attendants, and security guards at supermarkets who watch your car.', contextNote: 'ATMs are widely available; notify your bank before travelling' },
    { topic: 'SAFETY', title: 'Crime awareness is critical', body: 'Cape Town has real crime disparities. Stick to well-known tourist areas (Waterfront, City Bowl, Camps Bay, Sea Point) after dark. Avoid walking with visible valuables; leave your passport in the hotel safe. Uber and Bolt are far safer than hailing cabs from the street.', contextNote: 'Never leave anything on a car seat — smash-and-grab theft is common at traffic lights' },
    { topic: 'TRANSPORT', title: 'MyCiTi bus and Uber', body: 'The MyCiTi bus network covers the city centre, Waterfront, and some suburbs — it\'s cheap and air-conditioned. For Table Mountain and the Winelands, Uber is the most practical option. Car hire requires an IDP and confidence in left-hand driving.', contextNote: 'Traffic into the city from the Southern Suburbs is severe during rush hour' },
    { topic: 'DRESS', title: 'Layering for the Cape\'s weather', body: 'Cape Town\'s weather is notoriously changeable. Even in summer (Nov–Mar), the "Cape Doctor" (the South-Easter wind) can make afternoons cold. Pack a windproof layer. Hikers on Table Mountain are caught out by sudden cloud cover — bring a fleece regardless of forecast.', contextNote: 'UV radiation is intense — sunscreen is essential year-round' },
  ],

  'charleston-usa': [
    { topic: 'ETIQUETTE', title: 'Southern hospitality is real', body: 'Charleston\'s social culture is deeply rooted in courtesy. Strangers hold doors, make eye contact, and exchange pleasantries. Saying "sir" and "ma\'am" to service staff or elders is standard and appreciated, not awkward.', contextNote: 'Rushing or seeming impatient reads as rude — slow down' },
    { topic: 'FOOD', title: 'Lowcountry cuisine', body: 'Shrimp and grits, she-crab soup, and fried chicken from Husk or Bertha\'s Kitchen define Lowcountry cooking. Many restaurants serve Southern breakfast until noon. Sweet tea (iced, heavily sweetened) is the default beverage — ask for "unsweet" if you prefer plain iced tea.', contextNote: 'Portions are large; sharing dishes is completely acceptable' },
    { topic: 'DRESS', title: 'Smart-casual for evenings', body: 'Charleston has a strong culture of "Sunday best" dressing — people take pride in looking put-together at dinner. While not required, smart-casual at nicer restaurants is appreciated. Pastels and seersucker are genuinely popular, especially in spring.', contextNote: 'Shorts and flip-flops are fine during the day; less so at dinner restaurants' },
    { topic: 'TRANSPORT', title: 'Very walkable downtown', body: 'The historic district is entirely walkable and best explored on foot. DASH trolleys are free and cover the main tourist corridors. For beaches (Sullivan\'s Island, Isle of Palms), a car or Uber is necessary. Parking can be scarce and expensive downtown.', contextNote: 'Horse-drawn carriage tours are popular but book in advance' },
    { topic: 'SAFETY', title: 'Hurricane season awareness', body: 'Charleston is prone to hurricanes and tropical storms from June through November. If visiting in this window, monitor weather forecasts. The city floods during heavy rain due to low elevation — carry footwear you don\'t mind getting wet.', contextNote: 'High tides can flood some streets even without storms' },
    { topic: 'MONEY', title: 'Standard US tipping', body: 'Tipping 18–20% at restaurants and $1–2 per drink at bars is standard. Charleston has excellent fine dining; sommelier and sommelier tips are common. Many spots add an automatic gratuity for parties of 6 or more.', contextNote: 'Tax is added at checkout and not shown on prices' },
  ],

  'chicago-usa': [
    { topic: 'FOOD', title: 'Deep dish debate', body: 'Chicago deep-dish pizza is a casserole-style pie with thick crust, chunky tomato sauce on top, and dense cheese beneath. Lou Malnati\'s, Giordano\'s, and Pequod\'s are the legendary spots. Note: locals often eat thin-cut "tavern style" pizza daily — deep dish is the tourist showpiece.', contextNote: 'Never ask for ketchup on a Chicago hot dog — it is a cardinal sin' },
    { topic: 'ETIQUETTE', title: 'Midwest friendliness', body: 'Chicagoans are warm and direct — they will give you honest directions and chat on transit. The Midwest stereotype of friendliness is real here. Complaining about the city to a local (beyond weather) can feel unwelcoming; they are proud of Chicago.', contextNote: 'Calling Chicago "the second city" (to New York) is not appreciated' },
    { topic: 'TRANSPORT', title: 'The CTA "L" train', body: 'The Chicago Transit Authority\'s elevated train (the "L") circles the downtown Loop and extends into neighbourhoods. Buy a Ventra card for cheaper fares and free transfers. The Red Line runs 24 hours; most other lines stop late at night. Rideshares are common for airport runs.', contextNote: 'The Blue Line connects O\'Hare to downtown; the Orange Line serves Midway' },
    { topic: 'SAFETY', title: 'Neighbourhood awareness', body: 'Chicago is a city of distinct neighbourhoods with sharply varying safety levels. The Loop, River North, Lincoln Park, and Wicker Park are tourist-safe. Areas like Englewood and parts of the West Side have higher violent crime rates and are best avoided by visitors unless guided.', contextNote: 'Most tourist activity is in a relatively safe corridor — use common sense' },
    { topic: 'MONEY', title: 'High Chicago taxes', body: 'Chicago levies high combined state/city taxes. Restaurant meals carry a ~11% tax; hotels add another 17% or more in taxes and fees. Budget higher than you would in other US cities. Tipping follows standard US norms at 18–20% pre-tax.', contextNote: 'Cook County also adds its own sales tax layer' },
    { topic: 'DRESS', title: 'Layering for all seasons', body: 'The "Windy City" nickname is partially about lake-effect winds off Lake Michigan that make temperatures feel 10–15°F colder. Even in summer, bring a jacket for evenings near the lakefront. Winters are brutal — thermals, a parka, and waterproof boots are essential November–March.', contextNote: '"Hawk" is a local nickname for the icy wind' },
  ],

  'denver-usa': [
    { topic: 'SAFETY', title: 'Altitude sickness is real', body: 'Denver sits at 5,280 feet (1,609m) above sea level. Many visitors experience headaches, fatigue, and shortness of breath for the first 24–48 hours. Drink extra water, reduce alcohol and caffeine, and avoid strenuous exercise your first day. At mountain ski resorts (10,000ft+), symptoms are more pronounced.', contextNote: 'Alcohol hits harder at altitude — pace yourself' },
    { topic: 'FOOD', title: 'Green chile culture', body: 'Colorado\'s green chile (hatch or Pueblo peppers slow-cooked with pork) is the state\'s signature dish. It is poured over burritos, smothered on burgers, and served as a dip. Ordering a "smothered" burrito means it comes under a ladle of green chile — say "Christmas" to get both red and green.', contextNote: 'Spice levels vary significantly — ask first' },
    { topic: 'TRANSPORT', title: 'RTD light rail and rideshares', body: 'Denver\'s RTD light rail and bus network is decent but car-centric city planning means many attractions require wheels. The A Line connects the airport to Union Station in 37 minutes. For mountain trips (Rocky Mountain National Park, ski resorts), a car rental is essentially mandatory.', contextNote: 'Uber and Lyft are widely available downtown' },
    { topic: 'MONEY', title: 'Cannabis is legal — with caveats', body: 'Recreational cannabis is legal in Colorado for adults 21+. Dispensaries are plentiful and staff are helpful. You cannot consume in public spaces, parks, or hotel rooms (most prohibit it). Carry only what you purchased — crossing state lines is a federal offence.', contextNote: 'Cash is preferred at dispensaries due to federal banking restrictions' },
    { topic: 'ETIQUETTE', title: 'Outdoor culture etiquette', body: 'Denver has a deeply outdoorsy culture — trails, parks, and mountains dominate weekend life. Leave No Trace principles are taken seriously: pack out all trash, yield to uphill hikers, and keep dogs leashed where required. Trailheads fill early on weekends; arrive by 7am at popular spots.', contextNote: 'Saying hello to other hikers on trails is the norm' },
    { topic: 'DRESS', title: 'Layering for high-altitude weather', body: 'Mountain weather is unpredictable year-round — afternoon thunderstorms in summer and variable snow in spring and fall are common. Dress in layers: a moisture-wicking base, insulating mid-layer, and waterproof shell. At altitude, sun burns faster — SPF 50 is advisable.', contextNote: 'Cotton is dangerous in cold, wet mountain conditions — it holds moisture' },
  ],

  'dubai-uae': [
    { topic: 'ETIQUETTE', title: 'Public displays of affection', body: 'Public displays of affection between couples — including kissing — can result in fines or even detention under UAE law. Hand-holding between spouses is generally tolerated in tourist areas but exercise discretion in malls, beaches, and public spaces. Same-sex relationships are criminalised.', contextNote: 'Laws apply to tourists as well as residents' },
    { topic: 'DRESS', title: 'Modest dress in public', body: 'While Dubai is liberal by regional standards, modest dress is expected outside beach and resort areas. In malls, souks, and mosques, cover shoulders and knees. The Dubai Mall has a posted dress code. Many tourists are cited for entering mosques improperly dressed.', contextNote: 'Swimwear is acceptable at hotel pools and designated beaches only' },
    { topic: 'FOOD', title: 'Ramadan dining rules', body: 'During Ramadan, eating, drinking, and smoking in public between dawn and sunset is illegal — this includes tourists. Most malls and hotels have screened areas for daytime eating. Restaurant hours shift dramatically. Iftar (the sunset meal) is a wonderful social experience to join if invited.', contextNote: 'Ramadan dates shift by approximately 11 days each year — check in advance' },
    { topic: 'MONEY', title: 'No income tax but watch for fees', body: 'The UAE has no income tax and VAT is a low 5%. Hotels add significant taxes and service fees — the sticker price rarely reflects the final bill. Tipping is not obligatory but appreciated: 10% at restaurants, AED 5–10 for taxi drivers and hotel staff.', contextNote: 'ATMs dispense Dirhams; major cards accepted almost everywhere' },
    { topic: 'TRANSPORT', title: 'Metro and taxis', body: 'The Dubai Metro is clean, air-conditioned, and efficient along its two lines (Red and Green). Women and children have dedicated "Pink Carriages" at the front. RTA taxis are metered and reliable. Avoid unofficial taxis; use Careem (the regional Uber) or the official RTA app.', contextNote: 'Metro does not reach all attractions — JBR and Palm need taxis or bus' },
    { topic: 'SAFETY', title: 'Zero-tolerance drug policy', body: 'Dubai has an absolute zero-tolerance policy on drugs. This extends to prescription medications not carried with valid documentation — some sleeping pills and codeine-based drugs are controlled. Check the UAE Ministry of Health list before packing any medication.', contextNote: 'Alcohol is served at licensed venues; bringing it in from duty-free is allowed within limits' },
    { topic: 'LANGUAGE', title: 'Arabic phrases open doors', body: 'Arabic is the official language but English is universally spoken in Dubai\'s commercial and tourist areas. A few Arabic words go a long way: "Shukran" (thank you), "Marhaba" (hello), "Inshallah" (God willing — used for future plans). Never speak disparagingly about Islam or the ruling family.', contextNote: 'Most signs, menus, and announcements are in both Arabic and English' },
  ],

  'honolulu-usa': [
    { topic: 'ETIQUETTE', title: 'Aloha spirit is not a phrase', body: '"Aloha" means love, peace, and compassion — it is not just a greeting. Locals take genuine offence at tourists who treat Hawaiian culture as a backdrop for Instagram photos. Engage respectfully with hula, chant, and language; ask before photographing ceremonies.', contextNote: '"Mahalo" means thank you; "Aloha" serves as both hello and goodbye' },
    { topic: 'FOOD', title: 'Plate lunch and poke culture', body: 'The plate lunch (two scoops of rice, macaroni salad, and a protein) is Hawaiʻi\'s working-class staple. Poke bowls (cubed ahi tuna marinated in soy, sesame, and green onion) originated here — supermarket poke is often the best. Spam musubi (Spam on rice wrapped in nori) is a beloved local snack.', contextNote: 'Zippy\'s and L&L Hawaiian Barbecue are local chains serving authentic plates' },
    { topic: 'DRESS', title: 'Sun protection is non-negotiable', body: 'Hawaii\'s UV index is extreme year-round — the equatorial sun burns far faster than mainland US. Use reef-safe sunscreen (many chemical sunscreens are banned to protect coral), wear a hat, and reapply after swimming. Sun damage is cumulative even on cloudy days.', contextNote: 'Look for "reef-safe" labels — oxybenzone and octinoxate are prohibited' },
    { topic: 'SAFETY', title: 'Ocean safety warnings', body: 'The Pacific Ocean around Oʻahu can be deceptively dangerous. Always check surf conditions and obey warning signs at beaches. Hanauma Bay requires pre-booking; swimming at the North Shore in winter (Nov–Apr) when big-wave surf is active can be fatal for inexperienced swimmers.', contextNote: '"When in doubt, don\'t go out" is the local rule' },
    { topic: 'TRANSPORT', title: 'Waikīkī is walkable; island is not', body: 'The Waikīkī strip is walkable, with buses (TheBus) connecting to Honolulu\'s attractions. For the North Shore, Hanauma Bay, or Pearl Harbor, rent a car or book a tour. Rideshares are available. Traffic on H-1 freeway during rush hour is severe.', contextNote: 'Parking at Hanauma Bay is limited — arrive early or take the bus' },
    { topic: 'LANGUAGE', title: 'Hawaiian language and pronunciation', body: 'Hawaiian uses only 13 letters; the ʻokina (ʻ) is a glottal stop and changes meaning — Oʻahu is O-ah-hoo, not "Oh-ah-wah." Locals prefer the full "Hawaiʻi" spelling. Learning "Aloha," "Mahalo," and "Hau\'oli Makou" (we are happy) shows genuine respect.', contextNote: 'Mispronouncing place names is common but always try — locals appreciate the effort' },
  ],

  'istanbul-turkey': [
    { topic: 'ETIQUETTE', title: 'Remove shoes at mosques', body: 'All mosques require shoes to be removed before entering. Many provide plastic bags to carry them inside. Dress modestly — women should cover hair with a headscarf (often provided at the entrance), and both men and women should cover knees and shoulders. Avoid visiting during prayer times.', contextNote: 'The Blue Mosque is the most visited — queueing is worth it outside prayer hours' },
    { topic: 'FOOD', title: 'Turkish breakfast and tea culture', body: 'The traditional Turkish breakfast (kahvaltı) is elaborate: olives, white cheese, tomatoes, cucumbers, eggs, honey, and multiple breads. Tea (çay) is served in small tulip-shaped glasses throughout the day — refusing it is polite but accepting it is an invitation to conversation. Turkish coffee is small, strong, and served with grounds at the bottom.', contextNote: 'Never stir Turkish coffee — let the grounds settle before drinking' },
    { topic: 'MONEY', title: 'Cash in bazaars, cards elsewhere', body: 'The Grand Bazaar and Spice Market work best with cash in Turkish Lira. Bargaining is expected in the Grand Bazaar but not in price-marked shops. Inflation has been high in Turkey — exchange rates fluctuate; check the current rate before converting large amounts. ATMs in tourist areas are reliable.', contextNote: 'Haggling by offering 50–60% of the asking price is a reasonable starting point' },
    { topic: 'TRANSPORT', title: 'Istanbul\'s massive transit network', body: 'Istanbul\'s public transport is extensive: metro, tram, funicular, and ferry all use the Istanbulkart smart card (buy at any metro station). The Bosphorus ferries are both practical and scenic — take one to cross between the European and Asian sides. Traffic is severe; transit beats taxis for most journeys.', contextNote: 'The T1 tram line connects Sultanahmet, the Grand Bazaar, and Galata Bridge' },
    { topic: 'LANGUAGE', title: 'Key Turkish phrases', body: '"Merhaba" (hello), "Teşekkürler" (thank you), and "Lütfen" (please) are warmly received. Most people in tourist areas speak English. Learning a few words of Turkish signals respect — vendors and restaurant owners will often respond with warmth and sometimes a complimentary tea.', contextNote: '"Evet" is yes; "Hayır" (hi-er) is no' },
    { topic: 'SAFETY', title: 'Neighbourhoods and taxis', body: 'Istanbul is generally safe for tourists in areas like Sultanahmet, Beyoğlu, and Karaköy. Use only official yellow taxis or the BiTaksi app — meter should start at the base rate. Unlicensed taxis near tourist sights charge vastly inflated prices. Keep valuables close in crowded bazaars.', contextNote: 'Taksim Square can be rowdy on weekend nights' },
  ],

  'jaipur-india': [
    { topic: 'ETIQUETTE', title: 'Namaste and right-hand etiquette', body: '"Namaste" (pressing palms together with a slight bow) is the universal respectful greeting in Jaipur. When giving or receiving anything — food, money, gifts — use the right hand or both hands. The left hand is considered unclean. Pointing feet at people or sacred objects is rude.', contextNote: 'Shoes are removed before entering temples and many homes' },
    { topic: 'FOOD', title: 'Rajasthani cuisine', body: 'Rajasthan has a distinct cuisine: dal baati churma (lentils with baked wheat balls and sweetened flour), laal maas (fiery red mutton curry), and pyaaz ki kachori (onion-stuffed pastry). Vegetarian options dominate; Jaipur is a Jain-influenced city where many restaurants are fully vegetarian. Avoid tap water and unpeeled raw produce.', contextNote: 'Lassi (spiced yoghurt drink) from Rawat Mishthan Bhandar is locally famous' },
    { topic: 'DRESS', title: 'Conservative dress, especially for women', body: 'Jaipur is a traditional Rajput city. Women should wear salwar kameez, long skirts, or trousers with covered shoulders, particularly in markets, temples, and when visiting forts. Men in shorts are generally fine but long trousers are more respectful. Bright colours fit in well with the local palette.', contextNote: 'At temples, a dupatta (scarf) to cover the head is appreciated' },
    { topic: 'MONEY', title: 'Bargaining in Pink City markets', body: 'The Pink City\'s bazaars — Johari Bazaar (jewellery), Bapu Bazaar (textiles), and Tripolia Bazaar — expect negotiation. Opening at 40–50% of the asking price and working up slowly is standard practice. Never start bargaining unless you intend to buy — walking away after agreeing a price is considered dishonest.', contextNote: 'Government-approved emporiums (Rajasthali) have fixed, fair prices' },
    { topic: 'TRANSPORT', title: 'Auto-rickshaws and pre-paid taxis', body: 'Auto-rickshaws are the primary tourist transport inside the old city. Always agree on a price before departing — meters exist but are rarely used. For day trips (Amber Fort, Nahargarh), hire a driver through your hotel or use Ola/Uber. Camel and elephant rides at forts are controversial — research welfare concerns before participating.', contextNote: 'Drivers may offer commissions at gem shops — decline politely' },
    { topic: 'LANGUAGE', title: 'Hindi and Rajasthani phrases', body: '"Namaste" (hello/respectful greeting), "Dhanyavaad" (thank you), and "Kitna?" (how much?) cover most shopping interactions. Locals in markets often speak enough English for transactions. Attempting Hindi is appreciated and usually met with enthusiastic helpfulness.', contextNote: 'Rajasthani (Marwari) is distinct from Hindi but most locals are bilingual' },
    { topic: 'SAFETY', title: 'Tourist touts and scams', body: 'Jaipur has persistent touts around Hawa Mahal, Amber Fort, and the City Palace. The common "gem export" scam involves being befriended and persuaded to carry "duty-free" gems home to resell — it is a fraud. Politely but firmly declining persistent approaches is safer than engaging.', contextNote: 'Registered guides with RTDC (Rajasthan Tourism) carry ID cards — ask to see one' },
  ],

  'kathmandu-nepal': [
    { topic: 'ETIQUETTE', title: 'Namaste and clockwise circumambulation', body: '"Namaste" (palms together, slight bow) is used universally for greeting in Kathmandu. At Buddhist stupas (like Boudhanath) and temples, always walk clockwise — this is a sacred practice. Never step over prayer flags or touch a person\'s head, which is spiritually elevated.', contextNote: 'At Hindu temples, ask before entering — some are restricted to Hindus' },
    { topic: 'FOOD', title: 'Dal bhat and local eating habits', body: 'Dal bhat (lentil soup over rice with vegetable curry and pickles) is Nepal\'s national dish, eaten twice daily by most Nepalis. The Nepali saying goes "dal bhat power, 24 hour." Momos (dumplings with meat or veg) are the favourite snack. Avoid raw salads and unfiltered water — stick to boiled or bottled water.', contextNote: 'Ordering dal bhat at a local restaurant often comes with unlimited refills' },
    { topic: 'MONEY', title: 'Cash economy', body: 'Kathmandu is predominantly a cash economy. Carry Nepali Rupees for markets, taxis, and local restaurants. ATMs are available in Thamel and Patan but can run out of cash on weekends. Exchange rates at licensed money changers in Thamel beat airport rates. Bargaining is expected in markets.', contextNote: 'Never exchange money on the street — rates are manipulative and theft risk is real' },
    { topic: 'DRESS', title: 'Modest dress for temples', body: 'Remove shoes and cover shoulders and knees when entering temples and monasteries. Pashupatinath (a major Hindu site) restricts non-Hindu entry to outer areas only. Carry a sarong or light scarf for impromptu temple visits. Dress practically for dusty, uneven streets.', contextNote: 'Thamel (the tourist district) is relaxed; local neighbourhoods are more conservative' },
    { topic: 'TRANSPORT', title: 'Taxis and local buses', body: 'Metered taxis exist but meters are often ignored — negotiate a price before getting in or use the InDrive app. Local buses are cheap but chaotic and slow. For trekking trailheads (Lukla, Pokhara), domestic flights or tourist buses are the most practical options. Traffic and air pollution in Kathmandu are significant.', contextNote: 'Carry a face mask — Kathmandu has some of Asia\'s worst air quality' },
    { topic: 'SAFETY', title: 'Altitude and trekking preparation', body: 'Even Kathmandu Valley sits at 1,400m — higher treks (Everest Base Camp at 5,364m) require serious acclimatisation. Altitude sickness is life-threatening if ignored. Use a certified TIMS permit and hire a registered guide. Travel insurance covering high-altitude helicopter evacuation is essential for any serious trek.', contextNote: 'Never ascend more than 300–500m per day above 3,000m' },
    { topic: 'LANGUAGE', title: 'Nepali basics', body: '"Namaste" covers greetings; "Dhanyabad" means thank you; "Kati?" means how much. English is widely spoken in Thamel and tourist areas. Learning a few words of Nepali is unusual for a foreigner and genuinely delights locals.', contextNote: 'Nodding the head from side to side can mean "yes" in Nepal — different from Western convention' },
  ],

  'kyoto-japan': [
    { topic: 'ETIQUETTE', title: 'Bow as a greeting', body: 'The bow (ojigi) replaces the handshake. A 15-degree nod suffices for casual interactions; a 30-degree bow shows respect to elders or in formal settings. Never bow while on the phone — it is considered performative. Return every bow directed at you.', contextNote: 'Handshakes are uncommon unless initiated by the other person' },
    { topic: 'ETIQUETTE', title: 'Remove shoes at the door', body: 'Remove shoes when entering homes, traditional ryokan, and many temples. Never step onto tatami mats with slippers — only bare feet or socks belong there. Look for the step up at the entrance (genkan) as the signal to remove your footwear.', contextNote: 'Slippers are usually provided indoors; a separate pair is used in bathrooms' },
    { topic: 'FOOD', title: 'Kaiseki dining culture', body: 'Kyoto is famous for kaiseki, Japan\'s multi-course haute cuisine tradition rooted in temple food. Dining is slow, deliberate, and seasonal. Never rush a kaiseki meal. When eating ramen or noodles, slurping is acceptable and signals enjoyment.', contextNote: 'Saying "Itadakimasu" before eating is a respectful Japanese custom' },
    { topic: 'TRANSPORT', title: 'Buses and IC card', body: 'Kyoto\'s bus network is the most practical way to reach most temples. Buy an IC card (Suica or ICOCA) for seamless bus, subway, and train payments. The Kyoto City Bus day pass (500 yen) is worthwhile for heavy sightseers. Trains serve the outer temple districts like Arashiyama and Fushimi.', contextNote: 'Google Maps is excellent for Kyoto transit routing' },
    { topic: 'DRESS', title: 'Modest dress at temples', body: 'While most Kyoto temples don\'t enforce dress codes, modest clothing (covered knees and shoulders) is respectful. Many tourists rent kimono in the Gion area — this is culturally appreciated as long as it is worn properly. Ask rental shops for guidance on dressing correctly.', contextNote: 'Kimono rental includes dressing assistance and appropriate accessories' },
    { topic: 'SAFETY', title: 'Crowds at peak seasons', body: 'Cherry blossom (late March–April) and autumn leaves (November) draw enormous crowds — Fushimi Inari, Philosopher\'s Path, and Arashiyama Bamboo Grove become near-impassable in the afternoon. Visit these sites at dawn for a transformative experience. Accommodation books out months in advance.', contextNote: 'Weekday visits are significantly less crowded than weekends' },
  ],

  'las-vegas-usa': [
    { topic: 'ETIQUETTE', title: 'Casino floor etiquette', body: 'Casinos require patrons to be 21 or older on the gaming floor — ID will be checked even for those who appear older. Do not photograph casino floors; it is prohibited. Dealers and staff expect tips: $1–5 per hand at table games is customary. Never touch your bet once the dealer has started dealing.', contextNote: 'Alcohol is free on the casino floor while you are actively gambling' },
    { topic: 'FOOD', title: 'Buffets and dining strategy', body: 'Las Vegas buffets have declined in quality since the pandemic, but The Buffet at Wynn and Bacchanal at Caesars are still exceptional. For serious dining, the Strip\'s celebrity chef restaurants require reservations weeks in advance. Off-Strip on Paradise Road and Chinatown offer better value and authenticity.', contextNote: 'Most hotels offer "players club" discounts on dining — sign up for free' },
    { topic: 'MONEY', title: 'Manage your gambling budget', body: 'Set a strict gambling budget before you arrive and treat losses as the cost of entertainment. Slot machines have the worst odds; blackjack and video poker offer the best return rates. Casinos are engineered to disorient — clocks and windows are hidden deliberately.', contextNote: 'ATMs on casino floors charge the highest fees — withdraw cash beforehand' },
    { topic: 'TRANSPORT', title: 'Deuce bus and rideshares', body: 'The Deuce double-decker bus runs the entire Strip 24 hours for $6 (day pass $8). Las Vegas Monorail covers the mid-Strip with limited stops. For distances, Uber and Lyft are plentiful. Avoid unlicensed "limo" offers outside the airport — use official rideshares only.', contextNote: 'Walking the Strip looks short on a map but is 4.2 miles end-to-end' },
    { topic: 'DRESS', title: 'Dress codes at clubs', body: 'Las Vegas nightclubs are strict about dress codes. Men must wear dress shoes, smart trousers, and a collared shirt — trainers, shorts, and caps are grounds for rejection. Women have more latitude but revealing, fashionable attire is the norm. Bring confirmation of table reservations if applicable.', contextNote: 'Daytime pool parties (day clubs) have their own distinct casual-but-stylish standard' },
    { topic: 'SAFETY', title: 'Heat and hydration', body: 'Las Vegas summer temperatures exceed 110°F (43°C). The Strip involves far more walking than expected. Carry water constantly, seek air-conditioned interiors every 30 minutes, and avoid alcohol on empty stomachs in the heat. Even evenings can be dangerously hot June–September.', contextNote: 'Misting stations on the Strip provide some relief' },
  ],

  'lisbon-portugal': [
    { topic: 'FOOD', title: 'Pastéis de nata and café culture', body: 'The pastéis de nata (custard tart) from Pastéis de Belém — the original — requires a queue but is worth every minute. Portuguese coffee is exceptional: a "bica" is a short espresso, a "galão" is milky. Lunch is the serious meal; petiscos (small plates, like Portuguese tapas) are perfect for evenings.', contextNote: 'Asking for a "coffee with milk" gets you something very different from a latte — specify galão or meia-de-leite' },
    { topic: 'ETIQUETTE', title: 'Fado etiquette', body: 'Fado (the soulful national music) performances require absolute silence from the audience — conversation during a song is a serious faux pas. The music deals with saudade (longing, melancholy); chatting over it is considered deeply disrespectful. Applaud after each song, not during.', contextNote: 'Look for licensed fado restaurants in Mouraria, Alfama, and Bairro Alto' },
    { topic: 'TRANSPORT', title: 'Tram 28 and hills', body: 'Tram 28 is iconic but heavily overcrowded — consider walking the Alfama hills for a better experience. The Santa Justa Lift has long queues; the stairs beside it are free and fast. The Viva Viagem card covers metro, tram, and bus at reduced fares. Uber is cheap and plentiful.', contextNote: 'Lisbon\'s hills are steep — wear flat, grippy shoes on cobblestones (calçada portuguesa)' },
    { topic: 'MONEY', title: 'Cash and card mix', body: 'Lisbon is largely card-friendly, but older tascas (local taverns) and market vendors prefer cash. Tipping is appreciated but not compulsory — 5–10% at restaurants, rounding up at cafés. The city is good value compared to other Western European capitals, though prices have risen with tourism.', contextNote: 'Look for the menú do dia (set lunch) for excellent value meals' },
    { topic: 'LANGUAGE', title: 'Portuguese vs Spanish', body: 'Portuguese and Spanish are related but distinct. Lisboetas appreciate attempts at Portuguese ("Obrigado/Obrigada" for thank you, "Desculpe" for excuse me). Speaking Spanish to Portuguese people without asking is mildly impolite — always check if English works first (it usually does in Lisbon).', contextNote: '"Faz favor" is used to get a waiter\'s attention politely' },
    { topic: 'SAFETY', title: 'Pickpockets on trams and in Alfama', body: 'Tram 28, the Alfama, and Baixa-Chiado are prime pickpocket areas. Use a money belt or anti-theft bag. The main concern is opportunistic theft, not violence. Leave your passport in the hotel safe; carry a photocopy.', contextNote: 'Visible phone use while walking in busy streets invites phone snatching' },
  ],

  'london-england': [
    { topic: 'ETIQUETTE', title: 'Queue culture is sacred', body: 'Queuing is a fundamental part of British culture. Never jump a queue — the social disapproval will be silent but intense. On the Tube escalators, stand on the right so walkers can pass on the left. At bus stops, join the back of the queue without exception.', contextNote: '"Mind the gap" is both a warning and a cultural meme' },
    { topic: 'FOOD', title: 'Pub dining and ordering', body: 'In British pubs, you order and pay at the bar — there is no table service unless specified. "Round" culture means groups take turns buying everyone drinks. Food from gastropubs (the better pubs serving meals) is genuinely excellent. Sunday roast (noon–4pm) is a beloved institution.', contextNote: 'Pubs close between midnight and 2am depending on licence' },
    { topic: 'TRANSPORT', title: 'Oyster card and contactless', body: 'The Oyster card or any contactless debit/credit card taps in and out on the Tube, Overground, and buses. Never use a paper ticket — they are more expensive. Stand right on escalators, walk left. Night Tube runs Friday/Saturday on five lines. Heathrow Express is fast but pricey; the Elizabeth Line (Tube) is cheaper.', contextNote: 'Tap the same card in and out — switching cards mid-journey causes overcharging' },
    { topic: 'MONEY', title: 'Tipping norms', body: 'Service charge is often added to restaurant bills (10–12.5%) — check before adding more. If it\'s not included, 10–15% is standard. Pub bar staff are not typically tipped (you can offer to "have one for yourself"). Black cab drivers expect tips of 10–15%.', contextNote: 'Britain uses pounds sterling (GBP) — the euro is not accepted' },
    { topic: 'LANGUAGE', title: 'British English nuances', body: 'London\'s diverse population has created many accents — Cockney, Estuary, RP, and dozens more. "Cheers" means thank you, goodbye, and a toast. "Brilliant," "lovely," and "sorted" are universally positive. "Could do with…" means "I want." Understated complaint is the British way — "not bad" is a compliment.', contextNote: '"Pavement" is the sidewalk; "biscuit" is a cookie; "chips" are fries' },
    { topic: 'SAFETY', title: 'Phone theft epidemic', body: 'London has a serious phone theft problem — moped riders have been known to snatch phones from pedestrians\' hands. Never use your phone while walking near the kerb. Keep bags zipped and on your front in crowded areas like Oxford Street, the Tube, and Camden Market.', contextNote: 'Report theft to the Metropolitan Police within 24 hours for insurance claims' },
    { topic: 'DRESS', title: 'Umbrella over raincoat', body: 'London rain is drizzle, not downpour — a compact umbrella handles most days. The city is temperate; summer rarely exceeds 25°C (77°F) and rarely freezes in winter. Layers are more practical than heavy coats. Smart casual covers most London restaurants and venues.', contextNote: 'Pub gardens fill up the moment sun appears — Londoners are sun-desperate' },
  ],

  'los-angeles-usa': [
    { topic: 'TRANSPORT', title: 'Car culture is not a cliché', body: 'Los Angeles is genuinely built around cars. The Metro rail network is improving but most neighbourhoods — Malibu, Venice, Griffith Park, the Hills — are only practical by car or rideshare. Traffic on the 405 and 101 is severe during rush hours (7–10am, 4–7pm). Allow double the expected drive time during these windows.', contextNote: 'Freeway numbers are used without "the" only by people not from LA' },
    { topic: 'FOOD', title: 'LA\'s diverse food scene', body: 'Los Angeles has arguably the best and most diverse food in the US. Korean BBQ in Koreatown, birria tacos in Boyle Heights, Japanese ramen in Little Tokyo, and Ethiopian in Mid-City are all exceptional. The best tacos are almost never in restaurants — look for stands and trucks in neighbourhood streets.', contextNote: 'Farmers markets (Santa Monica on Wednesdays and Saturdays) are excellent for local produce' },
    { topic: 'ETIQUETTE', title: 'Industry culture and wellness', body: 'LA has a pervasive wellness and entertainment industry culture. Conversations may turn to acting, wellness routines, or creative projects — engage genuinely. "Let\'s definitely get coffee" often means nothing specific; Angelenos are friendly but non-committal in social invitations.', contextNote: 'Saying you\'re from LA means knowing which neighbourhood — just saying "LA" is vague' },
    { topic: 'MONEY', title: 'High cost of living', body: 'LA is one of the most expensive US cities. Parking can cost $30–50 per day in popular areas. Restaurant meals in mid-range establishments run $20–40 per person before tip. Consider staying in Culver City, Pasadena, or Long Beach for better accommodation value with transit access.', contextNote: 'Valet parking is common at restaurants — budget $5–10 for the tip' },
    { topic: 'SAFETY', title: 'Neighbourhood contrasts', body: 'LA\'s neighbourhoods vary dramatically in safety. Santa Monica, Silver Lake, Los Feliz, and West Hollywood are tourist-safe. Areas around Skid Row in downtown and parts of Compton and Inglewood carry higher crime risk. Use Uber at night rather than walking long stretches in unfamiliar areas.', contextNote: 'Leave nothing visible in a parked car — smash-and-grab theft is endemic' },
    { topic: 'DRESS', title: 'Effortlessly casual', body: 'LA style is deceptively casual — people invest in looking effortlessly dressed. Linen, tailored basics, and quality sneakers are universally acceptable. Only a few venues on the West Side enforce dress codes. Swimwear culture is pervasive along the coast from Malibu to Long Beach.', contextNote: 'Layers for the morning marine layer (coastal fog) that burns off by noon' },
  ],

  'marrakech-morocco': [
    { topic: 'ETIQUETTE', title: 'Hospitality and tea rituals', body: 'Moroccan hospitality is generous and sincere. When invited for mint tea ("atay"), accept — refusing is impolite. Tea is poured from a height to aerate it and served sweet; asking for less sugar is acceptable. Never rush the ritual; it signals that the relationship matters more than time.', contextNote: 'Three glasses of tea is traditional — leaving after one is fine' },
    { topic: 'DRESS', title: 'Conservative dress in the Medina', body: 'The Medina is a traditional Islamic city — women should cover shoulders, chest, and knees. Men in shorts are tolerated but long trousers are respectful. In Djemaa el-Fna square, female tourists in sleeveless tops attract unsolicited attention. Light, loose cotton clothing in the heat is both respectful and practical.', contextNote: 'Jilbab or kaftan-style clothing is widely sold in the souks and is a smart purchase' },
    { topic: 'MONEY', title: 'Bargaining in the souks', body: 'Haggling in the souks is expected and culturally enjoyable when done with humour. The opening price is often 3–5× the fair price — counter at a third and work up. Never accept the first price. If you enter a shop and show interest, you are expected to engage; a purchase is not obligatory but walking in and walking out without engagement is rude.', contextNote: 'Fixed-price cooperatives (artisan co-ops) offer fair pricing without negotiation' },
    { topic: 'FOOD', title: 'Eating in Djemaa el-Fna', body: 'The food stalls in Djemaa el-Fna are a Marrakech experience — harira soup, snail broth, grilled merguez, and fresh-squeezed orange juice. Stall touts are persistent; once seated, prices are set. Eating from stalls that have high turnover and are busy with locals is a good safety indicator.', contextNote: 'Orange juice from the square is fresh and cheap — a Marrakech ritual' },
    { topic: 'TRANSPORT', title: 'Petits taxis and walking the Medina', body: 'Red petits taxis (small cabs) are metered and cheap within Marrakech. Always insist the meter is on. The Medina itself is best explored on foot — many streets are too narrow for vehicles. Hiring a local guide to navigate the souks prevents getting hopelessly lost.', contextNote: 'GPS is unreliable in the Medina\'s winding alleyways' },
    { topic: 'LANGUAGE', title: 'Darija and French', body: 'Marrakech uses Moroccan Arabic (Darija) day-to-day, with French widely used in business and signage. "Salam" (hello/goodbye), "Shukran" (thank you), and "La, shukran" (no thank you — useful for declining touts) are essential. French is a safe fallback; English is less universal than in Northern Africa\'s coastal cities.', contextNote: 'Saying "La, shukran" with a smile deflects most persistent sellers' },
    { topic: 'SAFETY', title: 'Navigating touts and guides', body: 'Unofficial "guides" in the Medina will offer to show you around for free — fees are always expected at the end. Commission-based shops at the destination are part of the game. Hire certified guides through your riad or the official tourist office. The Medina is safe but keep one hand on your bag in crowded souks.', contextNote: 'If lost, entering any riad and asking for help is always safe' },
  ],

  'mexico-city-mexico': [
    { topic: 'FOOD', title: 'Taco culture', body: 'Mexico City\'s tacos are distinct from those elsewhere — small corn tortillas folded over meat, topped with onion, coriander, salsa, and a squeeze of lime. Never add sour cream or cheddar cheese (Tex-Mex). Al pastor (pork from a vertical spit with pineapple) and suadero (braised beef) are CDMX specialties. Tacos after midnight from street carts are a local rite.', contextNote: 'If a taco stand has a queue, it\'s the right choice' },
    { topic: 'ETIQUETTE', title: 'Politeness is paramount', body: 'Chilangos (Mexico City residents) are formal and polite in initial interactions. Address strangers as "usted" (formal you) until familiarity is established. "Disculpe" (excuse me) is used constantly. Bargaining at mercados is acceptable; pressuring or being aggressive is not.', contextNote: '"Güey" (mate/dude) is a casual term heard constantly among friends — do not use it with strangers' },
    { topic: 'TRANSPORT', title: 'Metro is the fastest way around', body: 'Mexico City\'s metro is vast, cheap (7 pesos per ride), and fast — it handles 5 million passengers daily. During rush hour (7–10am, 5–8pm), crowding is extreme. The first cars of some trains are women-only during peak hours; this is enforced. Metrobús (BRT) uses a card system; Uber is reliable and cheap above ground.', contextNote: 'Keep valuables in a front pocket on the metro — pickpocketing is common during peak hours' },
    { topic: 'SAFETY', title: 'Safety varies by colonia', body: 'Mexico City is safer than its reputation in tourist areas: Roma, Condesa, Polanco, Coyoacán, and Centro Histórico are well-patrolled. Avoid Tepito, Doctores, and parts of Iztapalapa. Uber is safer than street taxis (peseros); do not hail cabs from the street — only use app-based services or sitio (rank) taxis.', contextNote: 'Fake kidnappings via unlicensed taxis ("express kidnap") are a known risk — always use apps' },
    { topic: 'MONEY', title: 'Cash and tipping culture', body: 'Mexico has a tipping culture: 10–15% at restaurants (20% is generous), 10–20 pesos for parking attendants, and a few pesos for shopping bag packers at supermarkets. Carry smaller denominations — vendors often struggle to break 500-peso notes. ATMs in Oxxo convenience stores are reliable and charge low fees.', contextNote: 'Pesos, not dollars — paying in USD is accepted but at unfavourable rates' },
    { topic: 'LANGUAGE', title: 'Spanish proficiency pays dividends', body: 'English is not widely spoken outside Polanco and high-end hotels. Even rudimentary Spanish — "Buenos días," "Por favor," "¿Dónde está…?" — transforms how locals interact with you. Mexican Spanish uses "ustedes" for plural you (not vosotros as in Spain). Locals are patient and appreciate effort.', contextNote: 'Google Translate\'s camera mode works well for restaurant menus' },
    { topic: 'DRESS', title: 'Smart-casual for Polanco, casual elsewhere', body: 'Mexico City has an eclectic but fashionable style. Roma and Condesa are artsy-casual; Polanco is sleek and upscale. Layers are essential — the city sits at 2,240m and nights are cool year-round even when days feel warm. Carry a light jacket always.', contextNote: 'Altitude plus pollution: headaches common in the first 24 hours for some visitors' },
  ],

  'miami-usa': [
    { topic: 'FOOD', title: 'Cuban food culture', body: 'Miami\'s Cuban-American community has shaped the food culture profoundly. A "Cuban" (medianoche or classic) sandwich, café cubano (thimble-sized sweetened espresso), and croquetas de jamón are non-negotiable. Little Havana\'s Versailles restaurant is an institution; walk along Calle Ocho for authentic counters.', contextNote: 'Ordering "coffee" gets you American drip; say "café cubano" for the real thing' },
    { topic: 'TRANSPORT', title: 'Car is king', body: 'Miami is built for cars. The Metromover (downtown monorail) is free but covers only Brickell and downtown. The Metrorail goes to Coral Gables and Coconut Grove. South Beach and the Design District are walkable locally but most neighbourhoods require Uber or a rental car. Parking in South Beach is expensive and competitive.', contextNote: 'Ride-shares surge significantly on weekends in South Beach' },
    { topic: 'ETIQUETTE', title: 'Latin punctuality norms', body: 'Miami\'s Latin culture influences social timing. Social events (parties, casual dinners) routinely start 30–60 minutes after the stated time. Business meetings are on time. This cultural blend means nothing — arriving "fashionably late" to a social invitation is acceptable and sometimes preferred.', contextNote: 'If in doubt about an event\'s actual start time, text the host' },
    { topic: 'DRESS', title: 'Beach fashion and nightlife dress codes', body: 'South Beach has strict club dress codes — smart, stylish, and revealing. Sneakers, shorts, and caps are rejected at most clubs on Ocean Drive. Beach attire is confined to the beach and pool areas; walking through Wynwood or the Design District in a swimsuit is unusual. Miami fashion leans bold, tight, and tropical.', contextNote: 'Arrive at clubs before midnight to avoid queues and cover charges' },
    { topic: 'SAFETY', title: 'Sun and rip currents', body: 'Miami\'s UV is intense — apply SPF 30+ hourly and avoid peak sun (11am–3pm). Atlantic-side beaches have rip currents; swim between the flags and follow lifeguard instructions. Areas west of I-95 vary in safety — stick to South Beach, Wynwood, Brickell, and the Design District as a visitor.', contextNote: 'Hurricane season June–November: monitor forecasts if visiting then' },
    { topic: 'MONEY', title: 'High cost on South Beach', body: 'South Beach is significantly more expensive than the rest of Miami. Cocktails at rooftop bars cost $20–25; bottle service at clubs starts at hundreds. Eating one block off Ocean Drive cuts costs dramatically. Tipping follows standard US norms at 18–20%.', contextNote: 'Many clubs add a "resort fee" to cover charges — confirm before queuing' },
  ],

  'nashville-usa': [
    { topic: 'FOOD', title: 'Hot chicken and meat-and-three', body: 'Nashville hot chicken (fried chicken coated in a cayenne paste, served on white bread with pickles) originated here — Prince\'s and Hattie B\'s are the defining spots. The "meat-and-three" is a Southern tradition: choose a protein and three sides (mac and cheese, collards, cornbread). It\'s unpretentious, cheap, and extraordinary.', contextNote: 'Start at "medium" on hot chicken — "extra hot" is a genuine physical challenge' },
    { topic: 'ETIQUETTE', title: 'Country music culture and tipping musicians', body: 'Broadway\'s honky-tonks have live bands from noon to 3am. Bands play for tips — dropping $1–5 in the jar per song you enjoy is the done thing. Never talk loudly over the music or treat performers as background entertainment; they are professionals.', contextNote: '"Lower Broad" (Broadway) is touristy; locals go to East Nashville for live music' },
    { topic: 'TRANSPORT', title: 'Car essential city', body: 'Nashville has limited public transit. The WeGo bus system exists but is slow and not tourist-oriented. Music Row, 12 South, and East Nashville are most easily reached by Uber or rental car. BNA airport is compact — Uber into downtown is about 20 minutes off-peak.', contextNote: 'Parking downtown fills quickly during CMA Fest and major events — budget for lots' },
    { topic: 'MONEY', title: 'Tennessee has no income tax but check sales tax', body: 'Tennessee has no state income tax but a 9.5% sales tax (one of the highest in the US) applies to most goods. Restaurant tipping at 20% is standard. Bachelorette party culture has made Broadway tourism extremely expensive — prices at honky-tonks vary widely.', contextNote: 'Craft distilleries (Jack Daniel\'s is 80 miles away; Nashville has urban distilleries) are popular and reasonably priced for tastings' },
    { topic: 'LANGUAGE', title: 'Southern dialect and hospitality', body: '"Y\'all" is plural you — embrace it. "Bless your heart" can be sincere or subtly sarcastic depending on context; Southern speech layers meaning. Nashville locals are genuinely friendly and will give restaurant recommendations without being asked. Acknowledge the city\'s musical heritage, even if country music isn\'t your genre.', contextNote: 'Nashville has a growing non-country music scene — Americana, blues, and indie all thrive here' },
    { topic: 'SAFETY', title: 'Broadway crowds and alcohol', body: 'Lower Broadway is a dense party strip — keep an eye on drinks in crowded bars and watch your phone. Ride-shares are the safest way home; drunk driving arrests are taken seriously. The area is generally safe but opportunistic theft increases late at night on weekends.', contextNote: 'Use the Uber/Lyft designated pickup spots to avoid confusion in crowds' },
  ],

  'new-orleans-usa': [
    { topic: 'FOOD', title: 'The holy trinity of Creole food', body: 'New Orleans cuisine uses a "holy trinity" of onion, celery, and bell pepper as the base of dishes. Gumbo (a roux-thickened stew with okra, seafood, or sausage) and jambalaya (one-pot rice with meat and vegetables) are the defining dishes. Beignets at Café Du Monde with powdered sugar and café au lait are non-negotiable.', contextNote: 'Creole (urban, spiced, tomato-based) differs from Cajun (rural, spicier, no tomatoes)' },
    { topic: 'ETIQUETTE', title: 'Second line parade culture', body: 'Second line parades (neighbourhood brass band marches, often following a jazz funeral) are open public events — joining the second line (the following crowd) is welcomed. Mardi Gras beads are thrown from floats; catching them is not about flashing, as the media suggests — it\'s just festive crowd participation.', contextNote: 'Mardi Gras is a family event in many neighbourhoods; Bourbon Street is the exception' },
    { topic: 'TRANSPORT', title: 'Streetcars and walking', body: 'The St. Charles streetcar is one of the oldest continuously operating systems in the world and covers Magazine Street and the Garden District cheaply. Bourbon Street and the Quarter are walkable. Beyond the core, Uber is practical. Driving in the Quarter is inadvisable — streets are narrow and one-way.', contextNote: 'Open container laws allow drinking on public streets in New Orleans — a rare US exception' },
    { topic: 'LANGUAGE', title: 'New Orleans accent and vocabulary', body: 'The New Orleans accent is not a Southern drawl — it has more in common with Brooklyn. "Neutral Ground" is the median strip; "making groceries" means grocery shopping; "Where y\'at?" is a greeting meaning "how are you?" Neighbourhoods are called "wards"; upriver is "uptown," downriver is "downtown."', contextNote: '"Yat" is the affectionate term for a native New Orleanian' },
    { topic: 'SAFETY', title: 'Crime awareness', body: 'New Orleans has elevated violent crime rates, particularly in some residential areas. The French Quarter, Magazine Street, and the Garden District are well-policed for tourists. Avoid wandering off the grid in the Tremé late at night. Never flash expensive jewellery or large amounts of cash.', contextNote: 'Carry minimal valuables on Bourbon Street — pickpockets thrive in the crowds' },
    { topic: 'MONEY', title: 'Tips are part of musician\'s income', body: 'Street musicians, especially on Royal Street and in Jackson Square, play for tips. A dollar or two per song is appreciated. Restaurant tipping follows US norms at 18–20%. Brunch service (famously long in NOLA) tends to have higher automatic gratuities for large parties.', contextNote: 'Brunch is a full 3-hour event here — don\'t rush it' },
  ],

  'new-york-usa': [
    { topic: 'ETIQUETTE', title: 'Sidewalk and subway etiquette', body: 'New Yorkers walk fast and with purpose — stopping in the middle of a pavement to look at your phone is a cardinal sin. Keep right on sidewalks and stairs. On subway escalators, stand right, walk left. Never block the subway car doors. Giving up your seat for elderly or pregnant passengers is expected.', contextNote: '"Get out of the way" is delivered bluntly but without malice — take it as feedback, not aggression' },
    { topic: 'FOOD', title: 'Bagels, pizza, and deli culture', body: 'New York\'s bagels are distinct from anywhere else — denser, chewier, water-boiled before baking. Order "lox and schmear" (smoked salmon on cream cheese). NYC pizza (thin, foldable, sold by the slice) is eaten folded lengthwise. The classic deli sandwich is piled so high it must be pressed to eat.', contextNote: 'Never eat a pizza slice with a fork in New York — it\'s a social crime' },
    { topic: 'TRANSPORT', title: 'The subway is your best friend', body: 'The NYC subway runs 24/7 and covers all five boroughs — there is no other way to move as efficiently. Tap your contactless card or OMNY to pay; MetroCards still work but are being phased out. Avoid rush-hour trains on the 4/5/6 and L lines; they reach dangerous crowding levels. Night trains are slower but run continuously.', contextNote: 'Google Maps is excellent for subway routing; plan your route before entering the underground' },
    { topic: 'MONEY', title: 'Tipping expectations', body: 'Tipping is non-negotiable in New York: 20% at restaurants (22–25% is common for good service), $1–2 per drink at bars, $1 per bag for hotel porters, and 15% minimum for cabs/rideshares. Many restaurants add an automatic 18–20% service charge for parties of 5 or more. Failing to tip is considered deeply disrespectful to service workers.', contextNote: 'On restaurant tablets, the minimum suggested tip often starts at 18%' },
    { topic: 'SAFETY', title: 'Stay aware in tourist areas', body: 'Times Square, Midtown, and Penn Station have high pickpocket activity. Keep your phone in a front pocket and your bag zipped. Subway platforms late at night — particularly on less frequented lines — require vigilance. Overall, NYC is significantly safer than it was in the 1980s and 90s.', contextNote: 'If you feel unsafe on a platform, stand near the conductor\'s car (middle of the train)' },
    { topic: 'LANGUAGE', title: 'New York vernacular', body: '"The city" means Manhattan. "Uptown" and "downtown" refer to direction (not specific neighbourhoods). "Bodega" is the corner convenience store. "GOAT" in New York sports conversations always comes back to a local hero. Directions use numbered streets and avenues — learn the grid and you will never be lost.', contextNote: 'Saying "New York City" emphasises you are not from here' },
    { topic: 'DRESS', title: 'Wear walking shoes, not fashion shoes', body: 'You will walk 8–12 miles per day in New York. Fashion over function is a painful mistake — New Yorkers themselves wear comfortable shoes. Black is the default wardrobe colour. For evening dining in Manhattan, smart-casual is the minimum; a few upscale restaurants still enforce jacket requirements for men.', contextNote: 'Fashion Week changes the streets twice a year — September and February' },
  ],

  'paris-france': [
    { topic: 'ETIQUETTE', title: 'Always greet first', body: 'In France, beginning any interaction with "Bonjour" (or "Bonsoir" after 6pm) is not optional — it is the foundation of all social exchange. Entering a shop, addressing a waiter, or asking for directions without greeting first is considered brusque and rude. Even a brief "Bonjour, Madame/Monsieur" transforms the interaction.', contextNote: 'Failing to greet is the single most common tourist mistake in Paris' },
    { topic: 'FOOD', title: 'Dining hours and café culture', body: 'Parisian kitchens stop serving food between 2:30pm and 7:30pm. Plan meals accordingly — lunch runs noon–2:30pm, dinner from 7:30pm onwards. Sitting at a café table, even for just a coffee, entitles you to remain for as long as you like. Never rush; the garçon will not bring your bill until you ask ("L\'addition, s\'il vous plaît").', contextNote: 'Ordering a café allongé (long espresso) is more acceptable than asking for "American coffee"' },
    { topic: 'TRANSPORT', title: 'The Métro is essential', body: 'Paris\'s Métro is fast, cheap, and covers the entire city. The Navigo Easy card or contactless bank card works at turnstiles. Buy a carnet (now Navigo Easy charges) in bulk for savings. Most monuments are within walking distance of a metro station. Night buses (Noctilien) run when the Métro closes (12:30–5:30am).', contextNote: 'The airport RER B line connects CDG to central Paris in 35 minutes — far cheaper than a taxi' },
    { topic: 'MONEY', title: 'Tipping is appreciated, not mandatory', body: 'Service is legally included in all French restaurant bills. Leaving €1–2 on a café table or rounding up a restaurant bill by 5–10% is a genuine expression of satisfaction, not an obligation. Never tip a large percentage — it can seem patronising. Bars do not expect tips.', contextNote: 'Cash tips left on the table are taken; card gratuities less often reach staff directly' },
    { topic: 'LANGUAGE', title: 'Attempting French matters', body: 'Even broken French earns enormous goodwill in Paris. Begin with "Parlez-vous anglais?" (Do you speak English?) and most Parisians will switch with pleasure. Locals who seem aloof are observing a cultural standard of privacy in public — not being unfriendly. Genuine effort at French is disarming.', contextNote: '"Excusez-moi" and "Merci beaucoup" go a very long way' },
    { topic: 'DRESS', title: 'Parisian chic is understated', body: 'Parisians dress with intentional restraint — classic cuts, neutral palettes, quality fabrics. Bright tourist logos and overly casual attire (flip-flops in restaurants, sports jerseys) mark you as a visitor immediately. A blazer, neat jeans, and leather shoes cover almost every situation.', contextNote: 'Parisians rarely wear shorts outside summer and even then usually in parks, not on streets' },
    { topic: 'SAFETY', title: 'Seine riverbanks and tourist zones', body: 'Pickpocketing is rife near the Eiffel Tower, Sacré-Cœur, Champs-Élysées, and the Louvre. Groups of children asking you to sign a petition are a known distraction technique — the goal is your wallet. Use a cross-body bag, never keep a phone in a back pocket, and be especially alert on the RER B train from CDG.', contextNote: 'Report pickpocketing at the nearest commissariat de police for insurance claims' },
  ],

  'portland-usa': [
    { topic: 'FOOD', title: 'Food cart culture', body: 'Portland is the food cart capital of the US — not trucks, but permanent pods of carts grouped in lots. Pods like Cartopia (open late) and Mississippi Marketplace offer extraordinary variety at low prices. James Beard Award-winning chefs have opened here; the coffee scene (Stumptown, Coava, Heart) is world-class.', contextNote: 'Vegan and vegetarian options are abundant and not an afterthought — Portland takes this seriously' },
    { topic: 'ETIQUETTE', title: 'Progressive culture and social norms', body: 'Portland has a progressive, environmentally conscious culture. Recycling is taken seriously, single-use plastics are largely banned, and sustainability is a point of pride. Social interactions are casual and egalitarian — there is no formal dress code anywhere. Gentrification conversations are sensitive; listen more than you speak.', contextNote: '"Keep Portland Weird" is an actual cultural value' },
    { topic: 'TRANSPORT', title: 'MAX light rail and cycling', body: 'TriMet\'s MAX light rail, buses, and streetcar cover most of the city. The MAX Red/Blue lines connect the airport to downtown and continue to Hillsboro and Gresham. Portland has 350+ miles of bike lanes; rental bikes (Biketown) are dockless and practical. Uber and Lyft are present but locals often cycle.', contextNote: 'TriMet fares use a tap-in app or paper ticket — inspectors do check' },
    { topic: 'SAFETY', title: 'Homelessness and urban reality', body: 'Portland has a significant visible homelessness crisis in parts of downtown and along the waterfront. This is a social policy issue, not a violence risk for visitors. Keep normal urban awareness — do not leave valuables in cars and be aware in Old Town/Chinatown after dark.', contextNote: 'Most conflict situations are mental health or substance-related, not targeted at tourists' },
    { topic: 'MONEY', title: 'No sales tax in Oregon', body: 'Oregon has no sales tax — the price on the tag is what you pay. This makes Portland noticeably cheaper for shopping than California or Washington. Standard US restaurant tipping (18–20%) applies. Many Portland businesses are small and local — accepting credit cards but preferring it.', contextNote: 'Bring purchases back to Oregon from Washington or California for the savings to matter' },
    { topic: 'DRESS', title: 'Casual Pacific Northwest style', body: 'Portland dresses for weather: waterproof layers, quality boots, and fleeces are standard year-round. The city is chronically rainy October–May — a good rain jacket is essential. Social dress is relaxed without exception; overdressing is unusual and mildly conspicuous.', contextNote: 'Umbrella users are spotted as newcomers — Portlanders wear hoods' },
  ],

  'prague-czechia': [
    { topic: 'FOOD', title: 'Czech cuisine and pivnice culture', body: 'Czech food is hearty central European fare: svíčková (sirloin in cream sauce), goulash with bread dumplings (knedlíky), and roast pork with sauerkraut. The pivnice (beer hall) is the social heart of Prague — Czech lager (Pilsner Urquell, Kozel, Budvar) is among the world\'s finest and among Europe\'s cheapest. Food is secondary to the beer.', contextNote: 'Trdelník (the chimney cake sold at tourist stands) is not traditional Czech food — it was imported from Slovakia' },
    { topic: 'MONEY', title: 'Czech Koruna, not Euros', body: 'The Czech Republic uses the Czech Koruna (CZK) — not the Euro. Currency exchange offices in the tourist zone use terrible rates; use ATMs or exchange at a bank. Never exchange money at Wenceslas Square kiosks. Prague is very affordable — a beer costs CZK 50–80 (€2–3) in a local pub.', contextNote: 'Some tourist restaurants list prices in euros at unfavourable rates — pay in Koruna' },
    { topic: 'TRANSPORT', title: 'Prague metro and trams', body: 'Prague\'s metro has three lines (A, B, C) covering the core. Trams run 24 hours (night trams run less frequently). Buy a 90-minute transfer ticket or a 24-hour pass from machines at metro stations. Validate tickets before boarding. The airport bus (119) connects to Nádraží Veleslavín station on Line A.', contextNote: 'Inspectors check tickets frequently — fines for riding without are steep' },
    { topic: 'ETIQUETTE', title: 'Quiet reserve in public', body: 'Czechs are reserved with strangers and do not engage in small talk on public transport or in queues. This is not unfriendliness — it is privacy. Loud, boisterous tourist behaviour on trams and in restaurants draws visible disapproval. Service can seem brusque by American standards; it is simply efficient.', contextNote: 'Once trust is established, Czechs are warm and loyal friends' },
    { topic: 'SAFETY', title: 'Old Town tourist scams', body: 'Prague\'s tourist zone has well-known scams: strip club touts luring tourists to venues with inflated minimums, taxi drivers charging 10× the metered fare from the airport, and restaurants in Old Town Square with English-only menus and no visible prices. Bolt and Liftago apps are safer than street taxis.', contextNote: 'Always ask for a written menu price if dining anywhere on Old Town Square' },
    { topic: 'DRESS', title: 'Central European smart-casual', body: 'Prague residents dress smartly — not formally, but with care. The concert and opera culture (especially the Prague Philharmonic at Rudolfinum) expects smart dress. For restaurants and clubs in Vinohrady and Žižkov, smart-casual is appropriate. The city\'s cobblestones demand solid footwear.', contextNote: 'Czech winters are cold and wet — a waterproof coat and warm layers are essential from October' },
  ],

  'reykjavik-iceland': [
    { topic: 'SAFETY', title: 'Weather changes without warning', body: 'Iceland\'s weather is genuinely dangerous for unprepared visitors. Conditions can shift from sunshine to blizzard within an hour, year-round. Check vedur.is (the Icelandic Met Office) every morning. For highland and glacier activities, go only with a certified guide. Never hike on a glacier without crampons and an ice axe.', contextNote: 'safetravel.is tracks road and weather conditions in real time' },
    { topic: 'FOOD', title: 'Skyr, lamb, and fermented shark', body: 'Icelandic food is built around lamb (the most flavourful in the world due to open grazing), skyr (a thick yoghurt-like dairy product), and fresh Atlantic fish. Hákarl (fermented Greenlandic shark) is an acquired taste — try it at Þorramatur festival in January. The Reykjavik food scene has become genuinely world-class in the last decade.', contextNote: 'Pylsur (Icelandic hot dogs with fried onion and remoulade) from Bæjarins Beztu are a cultural institution' },
    { topic: 'MONEY', title: 'Iceland is expensive', body: 'Iceland is among Europe\'s most expensive destinations. Budget €60–100 per person per day at minimum excluding accommodation. Restaurant meals cost €25–50, a coffee €5–7. Card payments are universal — cash is almost never needed. Supermarkets (Bónus, Krónan) for self-catered meals cut costs dramatically.', contextNote: 'Happy hour (14:00–19:00 in some bars) is the best time to drink in Reykjavik' },
    { topic: 'TRANSPORT', title: 'Rental car for the Ring Road', body: 'Reykjavik itself is walkable and compact. For the Golden Circle, the Ring Road, or the Westfjords, a 4×4 rental car is essential — F-roads (highland roads) are legally restricted to 4WD vehicles and rental companies void insurance for violations. Drive on the left in winter with winter tyres (required by law October–April).', contextNote: 'Never drive off-road — it destroys fragile Icelandic moss that takes decades to grow back' },
    { topic: 'ETIQUETTE', title: 'Egalitarian society and hot pot culture', body: 'Iceland is a deeply egalitarian society — titles are rarely used, and even the President is called by their first name. The local geothermal pool (sundlaug) is the social hub where all classes mix. Shower fully with soap before entering — this rule is strictly enforced and culturally important.', contextNote: 'Reykjavik\'s Laugardalslaug and Vesturbæjarlaug pools are authentic local experiences' },
    { topic: 'LANGUAGE', title: 'Icelandic and English', body: 'Virtually all Icelanders under 60 speak excellent English — it is taught from age 6. Learning to pronounce key place names is both respectful and practical: "Eyjafjallajökull" is roughly "Ay-ya-fyat-la-yö-kool." "Takk" means thank you; "Halló" is hello. No attempt at Icelandic goes unappreciated.', contextNote: 'Icelandic is one of the world\'s least changed languages — Old Norse speakers could largely read modern Icelandic' },
    { topic: 'DRESS', title: 'Layering system for all seasons', body: 'The Icelandic weather rule: wear moisture-wicking base, insulating mid-layer, and a windproof/waterproof outer shell. This applies in summer too — July temperatures average only 12°C (54°F). Budget for quality gear if you haven\'t brought your own; Icelandic wool (lopapeysa sweaters) provide natural water resistance.', contextNote: 'Wool is the original Icelandic technical fabric — available in Kolaportið flea market at good prices' },
  ],

  'rio-de-janeiro-brazil': [
    { topic: 'ETIQUETTE', title: 'Carioca warmth and physical greetings', body: 'Cariocas (Rio residents) are physically warm — greetings involve cheek kisses (one for locals, two for some regions) and hugs for friends. Personal space is smaller than Northern Europe or the US. Engaging conversation, smiling, and accepting hospitality are integral to the culture.', contextNote: '"Carioca" refers specifically to Rio residents; "Paulistano" refers to São Paulo residents' },
    { topic: 'FOOD', title: 'Churrascaria and açaí culture', body: 'A churrascaria (Brazilian steakhouse) works on the "rodízio" system: for a fixed price, servers bring skewers of different meats continuously until you turn the token to red to stop. Feijoada (black bean and pork stew) is the national dish, traditionally served on Saturdays. Açaí bowls topped with granola are a daily Carioca ritual after the beach.', contextNote: 'Caipirinha (cachaça, lime, sugar) is the national cocktail — made right, it is transformative' },
    { topic: 'SAFETY', title: 'Crime awareness is essential', body: 'Rio has significant crime disparities. Favela tourism is possible through legitimate guided tours but do not wander into them unguided. Leave jewellery and expensive watches in the hotel. On the beach, only bring what you need — phone theft from sunbathers is common. Avoid displaying phones on the street in Lapa at night.', contextNote: 'Most tourist areas (Ipanema, Copacabana, Santa Teresa with a guide) are well-patrolled' },
    { topic: 'TRANSPORT', title: 'Metro, VLT, and uber', body: 'The Rio Metro runs two lines covering key areas — Ipanema, Copacabana, Flamengo, and downtown. The VLT (light rail) covers the port area and Cinelândia. Uber is cheap and far safer than street taxis. Avoid collective vans (kombis) and unlicensed taxis. For Pão de Açúcar (Sugarloaf), combine Metro + bus.', contextNote: 'During Carnaval, public transport is overwhelmed — plan significant extra time' },
    { topic: 'DRESS', title: 'Beach wear and urban dress', body: 'The tiny Havaianas-and-sunscreen beach aesthetic is authentic, but moving through the city in swimwear draws attention. Cariocas are well-dressed outside the beach zone. The fio dental (dental floss bikini) on Ipanema is culturally normal for women; cover up when heading inland.', contextNote: 'Havaianas originated in Brazil — buying them here is cheap and authentic' },
    { topic: 'MONEY', title: 'Pix and cash', body: 'Brazil\'s Pix instant payment system is widely used — connect a Brazilian bank account or Pix-compatible card to pay instantly. For tourists, cash in Reais is practical for markets and smaller vendors. Bargaining at street markets (Feira Hippie de Ipanema) is acceptable. ATMs dispense Reais; use Bradesco or Banco do Brasil for lower international fees.', contextNote: 'Never carry your entire daily budget to the beach' },
  ],

  'rome-italy': [
    { topic: 'FOOD', title: 'Roman pasta and when not to eat near monuments', body: 'Roman pasta has four great classics: cacio e pepe (pecorino and black pepper), carbonara (guanciale and egg, never cream), amatriciana (tomato, guanciale, pecorino), and gricia (guanciale and pecorino). Restaurants within 100m of the Colosseum, Trevi Fountain, and Piazza Navona are almost universally overpriced and mediocre — walk two streets away. Lunch from 12:30pm; dinner from 8pm.', contextNote: 'Ordering a cappuccino after 11am marks you as a tourist; espresso is afternoon and evening standard' },
    { topic: 'ETIQUETTE', title: 'Church dress codes and opening hours', body: 'Rome has hundreds of churches open to tourists, most with strict dress codes: no sleeveless tops, bare shoulders, shorts, or short skirts. The Vatican Museums and St. Peter\'s Basilica enforce this rigorously. Carry a light scarf for shoulders. Many churches close between noon and 3pm for riposo (rest period).', contextNote: 'The Sistine Chapel requires complete silence — guards enforce this vocally' },
    { topic: 'MONEY', title: 'Coperto (cover charge) and tipping', body: 'Most sit-down restaurants charge a coperto (cover charge) of €1.50–4 per person — this is listed on the menu and is legal. Tipping is not customary in Italy; rounding up or leaving €1–2 at the end of a good meal is generous. Never tip on a card — leave cash on the table if you want it to reach the waiter.', contextNote: 'If a restaurant does not list a coperto, ask before ordering' },
    { topic: 'TRANSPORT', title: 'Metro, bus, and walking', body: 'Rome\'s Metro has only two practical lines (A and B) — it was impossible to expand due to constant archaeological discoveries during digging. Buses cover far more of the city but are slower and crowded. Validate your ticket before boarding any public transport — inspectors issue large fines. Walking remains the best way to discover Rome.', contextNote: 'Electric scooters (Lime, Bird) are increasingly common but traffic is chaotic for the uninitiated' },
    { topic: 'LANGUAGE', title: 'Italian pleasantries', body: '"Buongiorno" (until 1pm) and "Buonasera" (from 1pm onward) are the essential greetings. "Prego" means you\'re welcome, please, and go ahead. "Grazie mille" (a thousand thanks) is warmly received. Romans are passionate conversationalists — gestures are half the language and completely authentic.', contextNote: '"Cameriere" calls the waiter; waving or snapping fingers is offensive' },
    { topic: 'SAFETY', title: 'Pickpockets at key monuments', body: 'The Colosseum, Vatican, Trevi Fountain, and the Termini station area have Rome\'s highest pickpocket concentrations. The classic approach: a person bumps into you while an accomplice takes your belongings from the other side. Use an anti-theft bag, keep your wallet in a front pocket, and be suspicious of anyone who approaches to sell roses or beads.', contextNote: 'The Termini area after dark requires extra vigilance' },
    { topic: 'DRESS', title: 'Bella figura — looking good matters', body: 'Romans take "bella figura" (making a good impression) seriously. Dressing well is a social value, not vanity. Even casual wear in Rome tends to be well-fitted and coordinated. For evening dining or any church visit, smart attire is appropriate. Gym wear in restaurants is unusual and mildly frowned upon.', contextNote: 'Italian fashion is accessible here — quality leather goods in the city centre are good value compared to elsewhere' },
  ],

  'san-francisco-usa': [
    { topic: 'ETIQUETTE', title: 'Tech culture and social norms', body: 'San Francisco has a strong culture of progressive values and social awareness. Conversations about housing, homelessness, and tech gentrification are locally charged — listen before opining. "SF" is the local abbreviation; "Frisco" is used only by people who aren\'t from the area.', contextNote: 'Bay Area locals often specify their exact city — "San Francisco" vs. "Oakland" vs. "Berkeley" matters significantly' },
    { topic: 'FOOD', title: 'Mission burritos and sourdough', body: 'The Mission District burrito is distinct: a foil-wrapped monster with rice, beans, meat, pico de gallo, sour cream, and guacamole all inside. La Taqueria and El Farolito are the contested GOAT institutions. San Francisco sourdough starter dates back to Gold Rush bakers; Boudin Bakery on Fisherman\'s Wharf sells bread made from the original 1849 culture.', contextNote: 'Clam chowder in a sourdough bread bowl is a tourist staple worth trying once' },
    { topic: 'TRANSPORT', title: 'BART, Muni, and rideshares', body: 'BART (Bay Area Rapid Transit) connects the airport to downtown in 30 minutes and extends to Oakland and Berkeley. Muni (the city\'s internal transit: streetcars, light rail, buses) uses a Clipper card or contactless payment. The city is small but hilly — cable cars are tourist icons but Muni buses are more practical. Rideshares have surge pricing during tech events.', contextNote: 'BART is reliable weekdays; weekend service is less frequent' },
    { topic: 'SAFETY', title: 'Neighbourhood contrasts', body: 'San Francisco has stark contrasts. The Tenderloin and parts of SoMa have open drug use and high theft rates; the Financial District, Castro, Noe Valley, and the Mission are generally safer. Smash-and-grab car theft is epidemic — do not leave anything in a parked car, including bags in the trunk. Auto break-ins occur even in broad daylight.', contextNote: 'Report break-ins online at sfpd.org — required for insurance claims' },
    { topic: 'DRESS', title: 'Microclimates require layers', body: 'San Francisco has intense microclimates — it can be 65°F (18°C) in the Mission and 50°F (10°C) with heavy fog in the Sunset simultaneously. The Bay\'s "Karl the Fog" can swallow summer mornings entirely. Always carry a layer, even in July. Casual tech-company style (Patagonia vests, selvedge jeans, Allbirds) is the unspoken dress code.', contextNote: 'June gloom (fog-heavy mornings in early summer) is locally acknowledged and planned around' },
    { topic: 'MONEY', title: 'High cost of living spills into tourism', body: 'San Francisco is one of the US\'s most expensive cities. Mid-range restaurant meals run $25–45 per person, cocktails are $18–22, and parking can cost $40–60 per day downtown. Tipping at 20% is standard. The Ferry Building Marketplace on Saturday mornings offers excellent food at accessible prices.', contextNote: 'Avoid restaurants around Fisherman\'s Wharf for value — they cater entirely to tourists' },
  ],

  'seattle-usa': [
    { topic: 'FOOD', title: 'Seafood and coffee culture', body: 'Seattle\'s Pike Place Market has the world\'s most theatrical fishmongers — the Pike Place Fish Co. throw orders across the market. Dungeness crab, Pacific oysters, and salmon are exceptional. Seattle is the birthplace of Starbucks (the original is at Pike Place) but the city\'s independent coffee scene (Victrola, Caffe Vita, Elm) is superior. Espresso is the standard; drip coffee is available but secondary.', contextNote: 'Ordering a "Seattle-style" coffee doesn\'t mean much — ask for specific preparations' },
    { topic: 'TRANSPORT', title: 'Link Light Rail and rideshares', body: 'Sound Transit\'s Link Light Rail connects Sea-Tac Airport to Capitol Hill, downtown, and beyond in a straight north-south line. The ORCA card covers light rail, buses, and Sounder train. Seattle has improving bike infrastructure (Lime and Spin e-bikes). Rideshares are reliable and surge around major events at Climate Pledge Arena.', contextNote: 'Traffic on I-5 and SR-99 is severe during rush hours — allow significant buffer time' },
    { topic: 'ETIQUETTE', title: 'The Seattle Freeze', body: 'The "Seattle Freeze" is a well-documented local phenomenon: residents are polite and helpful but do not easily convert acquaintances to close friends. It is not coldness — it is a Northern Pacific temperament. Social events, outdoor activities, and joining climbing or running clubs are the genuine ways in. Surface friendliness is authentic; depth takes time.', contextNote: 'Outdoorsy activities (hiking, climbing, kayaking) are universally social lubricants' },
    { topic: 'SAFETY', title: 'Open drug use and urban context', body: 'Seattle is navigating a public drug crisis, particularly in the Capitol Hill and downtown areas. Open drug use is visible in some streets. This is a public health issue, not direct visitor danger, but exercise normal urban awareness. Vehicles are frequently broken into — leave nothing visible in a parked car.', contextNote: 'Pioneer Square and parts of Belltown require heightened awareness at night' },
    { topic: 'DRESS', title: 'REI headquarters aesthetic', body: 'Seattle is an outdoor gear city — Gore-Tex, fleece, and waterproof boots are genuinely practical year-round given 150+ rainy days. The "REI headquarters" aesthetic (technical wear as everyday wear) is genuine and not ironic. Umbrellas mark newcomers; hooded rain jackets are the authentic choice.', contextNote: 'Seattle summers (July–September) are spectacular — warm, sunny, and completely unlike the grey reputation' },
    { topic: 'MONEY', title: 'Washington has no income tax', body: 'Washington State has no income tax but a 10.3% sales tax in Seattle. Standard US tipping applies (18–20% at restaurants). Seattle has a robust minimum wage ($17+/hour) which many restaurants pass on as a "service charge" separate from tips — read your bill carefully as this is not always a tip to staff.', contextNote: 'Technology-industry pricing has elevated Seattle costs significantly in the last decade' },
  ],

  'singapore': [
    { topic: 'ETIQUETTE', title: 'Public behaviour laws', body: 'Singapore enforces laws on public behaviour that are advisory-level in most Western countries. Littering (minimum $300 fine), jaywalking, chewing gum in public (banned from sale), and vandalism carry significant penalties. These laws are enforced — tourists are not exempt.', contextNote: 'Failure to flush a public toilet can technically be fined — it is enforced' },
    { topic: 'FOOD', title: 'Hawker centre culture', body: 'Singapore\'s UNESCO-recognised hawker centres are the best place to eat in the country — cheap, extraordinary, and entirely authentic. Hainanese chicken rice, laksa, char kway teow, and roti prata are essential. Queue for what everyone else is queuing for. Tables are shared; leave your tray at a central clearing point when done.', contextNote: 'Reserving a table with a tissue packet (a Singapore custom) is genuine and respected' },
    { topic: 'MONEY', title: 'Cashless and expensive', body: 'Singapore is highly cashless — PayNow, PayLah!, and credit cards work almost everywhere. It is also one of Asia\'s most expensive cities; budget SGD 150–300 (€100–200) per day for mid-range travel. Hawker food remains remarkably affordable at SGD 3–8 per dish. No tipping is necessary — service charge (10%) is added to restaurant bills.', contextNote: 'Alcohol is expensive due to high sin taxes — hawker beers cost more than the food' },
    { topic: 'TRANSPORT', title: 'MRT: Asia\'s best transit system', body: 'Singapore\'s MRT is one of Asia\'s most reliable metro systems — air-conditioned, punctual, and cheap. The EZ-Link card or any contactless card taps in and out. Eating and drinking on the MRT carries a SGD 500 fine. Grab (Southeast Asia\'s Uber) is widely used for areas not served by rail.', contextNote: 'Most tourist sights are within 5–10 minutes\' walk of an MRT station' },
    { topic: 'LANGUAGE', title: 'Four official languages and Singlish', body: 'Singapore has four official languages: English, Mandarin, Malay, and Tamil. English is the lingua franca and all signage is in English. Singlish (Singaporean English creole) is used informally: "Can!" means yes/agreed; "Lah," "Lor," "Mah" are sentence-ending particles signalling emphasis or finality. Understand it; mimicking it as a tourist is awkward.', contextNote: '"Shiok" means delicious/amazing; "Kiasu" means fear of missing out (a defining cultural value)' },
    { topic: 'DRESS', title: 'Smart-casual everywhere', body: 'Singapore\'s heat and humidity (30°C+, 80%+ humidity year-round) means lightweight, breathable clothing is essential. Air conditioning is so aggressive inside malls and restaurants that carrying a light cardigan is practical. Gardens by the Bay and outdoor attractions require sun protection. Temple visits require covered shoulders and knees.', contextNote: 'Most rooftop bars and upmarket restaurants have smart-casual dress codes' },
    { topic: 'SAFETY', title: 'One of Asia\'s safest cities', body: 'Singapore is consistently rated one of the world\'s safest cities. Violent crime is extremely rare. Standard precautions apply (don\'t leave valuables unattended) but the city functions with an unusual level of public trust. Scams are rare and usually digital rather than in-person.', contextNote: 'Drug trafficking carries the death penalty in Singapore — this is not a hypothetical' },
  ],

  'sydney-australia': [
    { topic: 'ETIQUETTE', title: 'Egalitarianism and "tall poppy" culture', body: 'Australians are informal and egalitarian — excessive formality or status signalling is viewed with suspicion. The "tall poppy syndrome" means anyone who seems to elevate themselves above others is gently cut down. Use first names, engage in self-deprecating humour, and never take yourself too seriously.', contextNote: '"No worries," "She\'ll be right," and "arvo" (afternoon) are genuinely everyday expressions' },
    { topic: 'FOOD', title: 'Brunch culture and coffee', body: 'Sydney invented the modern café brunch culture that spread globally. Avocado toast, flat whites, and all-day eggs Benedict are sincere, not ironic. Melbourne claims the coffee crown but Sydney\'s Inner West (Newtown, Surry Hills) has exceptional roasters. The flat white is Sydney\'s gift to the world — always order one.', contextNote: 'Asking for a "regular coffee" typically gets a latte; a "long black" is an Americano' },
    { topic: 'TRANSPORT', title: 'Opal card for all transit', body: 'Sydney\'s transport uses the Opal card — load it at any 7-Eleven or station and tap on/off for trains, buses, ferries, and light rail. The ferry from Circular Quay to Manly is one of the world\'s great commutes and costs the same as a train ride. The Airport line charges an extra station access fee (around $15 each way).', contextNote: 'The Manly Ferry operates rain or shine — it has beautiful harbour views from the upper deck' },
    { topic: 'SAFETY', title: 'Sun safety in Australia', body: 'Australia has the world\'s highest rate of skin cancer. The UV index regularly hits 11+ (extreme) even in autumn. Apply SPF 50+ sunscreen every 2 hours, wear a hat, and seek shade between 10am–3pm. "Slip, slop, slap" (slip on a shirt, slop on sunscreen, slap on a hat) is a government campaign that has been taught since the 1980s.', contextNote: 'UV is dangerous even on overcast days in Australia' },
    { topic: 'MONEY', title: 'Tipping is evolving', body: 'Historically Australia did not have a tipping culture — waitstaff are paid a living wage including weekend penalty rates. Tipping has become more common in Sydney\'s fine dining and hospitality scene; 10% is generous, not expected. Round up taxi fares. Card payment prompts now frequently suggest gratuity options.', contextNote: 'Sunday and public holiday surcharges (10–15%) are legal and standard — not a scam' },
    { topic: 'LANGUAGE', title: 'Australian slang', body: '"Arvo" is afternoon; "brekky" is breakfast; "servo" is a petrol station; "bottle-o" is a liquor store. "How ya going?" is a greeting, not a genuine inquiry about your state of travel. "Thongs" are flip-flops — Australians will immediately laugh at American English usage of the word.', contextNote: '"She\'ll be right" means everything will work out fine — a defining national philosophy' },
    { topic: 'DRESS', title: 'Beach culture is pervasive', body: 'Sydney\'s beach culture means swimwear, board shorts, and thongs are acceptable attire in coastal suburbs at virtually any time. Moving into the CBD, smart-casual is appropriate. Bondi and Manly have a relaxed but put-together beachside aesthetic. Sun protection — hat, long sleeves, rash vest — is not optional.', contextNote: 'Rash vests (surf shirts) are worn for sun protection, not modesty' },
  ],

  'tokyo-japan': [
    { topic: 'ETIQUETTE', title: 'Quiet in public spaces', body: 'Tokyo\'s public spaces — trains, escalators, waiting areas — operate in near-silence. Talking on the phone on trains is considered extremely rude. Conversations are kept quiet and brief. Never eat or drink while walking in central Tokyo. These norms apply to everyone, not just tourists.', contextNote: 'Train carriages marked with a phone icon are "quiet carriages" — no calls at all' },
    { topic: 'FOOD', title: 'Ramen, sushi, and eating alone culture', body: 'Tokyo has more Michelin-starred restaurants than any city in the world. Eating at the counter alone is entirely normal and respected — many ramen bars have individual booths with curtains specifically for solo diners. Slurping noodles signals enjoyment. For sushi, say "omakase" (chef\'s choice) at a counter to get the best experience.', contextNote: 'Cash is still expected at many traditional ramen shops and izakayas' },
    { topic: 'MONEY', title: 'IC card for everything', body: 'The Suica or Pasmo IC card works on all Tokyo rail, subway, bus, and many convenience store payments. Buy at any JR station with a machine that has an English option. Load 2,000–3,000 yen immediately. The 24- or 72-hour metro passes are worth it for heavy sightseers.', contextNote: 'Convenience stores (konbini) accept IC cards and are extraordinary for quick, cheap meals' },
    { topic: 'TRANSPORT', title: 'The JR and Tokyo Metro system', body: 'Tokyo\'s train network is the world\'s most complex but also among the most reliable. Google Maps handles routing perfectly in English. The JR Yamanote Line (green, circular) connects major hubs: Shibuya, Shinjuku, Harajuku, Ueno. Avoid rush hour (7:30–9:30am) on major lines — compression is extraordinary and uncomfortable.', contextNote: 'Staff in orange uniforms at busy stations help push passengers into full carriages during peak times' },
    { topic: 'SAFETY', title: 'Extremely safe, with caveats', body: 'Tokyo is one of the world\'s safest cities. Lost property is almost always returned. Violent crime is virtually unknown for tourists. The main caution is in areas like Kabukicho (Shinjuku\'s red light district) where aggressive touts from certain hostess bars target tourists with steep bills. Don\'t enter any club without confirmed prices.', contextNote: 'Never leave a bag unattended — it will be reported and security will be called, not stolen' },
    { topic: 'LANGUAGE', title: 'Key Japanese phrases', body: '"Sumimasen" (excuse me/sorry — most versatile word in Japan), "Arigatou gozaimasu" (thank you, formal), "Eigo wa wakarimasu ka?" (do you understand English?). Most station staff speak some English. Carrying a phrase book or using Google Translate\'s camera mode for menus is universally practical and appreciated.', contextNote: 'Google Translate\'s real-time camera translation handles Japanese menus very well' },
    { topic: 'DRESS', title: 'Smart casual is the Tokyo baseline', body: 'Tokyo\'s fashion culture is sophisticated and experimental — from Harajuku street fashion to Ginza luxury. For daily tourism, clean smart-casual is baseline respectful. At onsen (hot spring baths), tattoos are banned at most establishments — check the policy before visiting. Comfortable walking shoes for the 10–15 miles you will walk daily are essential.', contextNote: 'Tattoo-friendly onsen exist and can be found online — search "tattoo-friendly onsen Tokyo"' },
  ],

  'vienna-austria': [
    { topic: 'FOOD', title: 'Coffeehouse culture', body: 'The Viennese coffeehouse is a UNESCO-recognised cultural institution — a place to sit for hours with a single Melange (a half-espresso, half-steamed milk creation) and a newspaper. No one will rush you. Classic coffeehouses (Café Central, Café Hawelka, Café Schwarzenberg) serve coffee with a glass of cold water as a matter of course.', contextNote: 'Ordering an "Einspänner" (double espresso in a glass with whipped cream) is the classic Viennese order' },
    { topic: 'ETIQUETTE', title: 'Formal culture and titles', body: 'Vienna is one of Europe\'s most formally polite cities. Academics, doctors, and senior professionals are addressed with their title ("Herr Doktor," "Frau Professorin"). In shops and restaurants, "Bitte" (please) and "Danke" (thank you) are expected at every transaction. Skipping pleasantries is perceived as rudeness.', contextNote: 'Austrians say "Grüß Gott" (God greet you) rather than "Hallo" in formal contexts' },
    { topic: 'TRANSPORT', title: 'U-Bahn and tram network', body: 'Vienna\'s public transport (U-Bahn, tram, bus) is extensive and punctual. The Wiener Linien day or 72-hour ticket covers all zones and represents excellent value. Validate tickets on the first use in the machine — inspectors check frequently. Night buses run when the U-Bahn stops after midnight.', contextNote: 'Tram 1 and 2 circle the Ringstraße past major cultural institutions — a free sightseeing tour' },
    { topic: 'MONEY', title: 'Austria uses euros; tipping is modest', body: 'Tipping in Vienna is genuine but modest — 5–10% at restaurants (rounding up is common), €1–2 for coat check, €0.50–1 for bathroom attendants. It is customary to tell the server the total you wish to pay when settling the bill ("Machen Sie dreißig" — "make it thirty") rather than waiting for change.', contextNote: 'Saying "Stimmt so" (keep the change) is the standard tip acknowledgement' },
    { topic: 'LANGUAGE', title: 'Austrian German differences', body: 'Austrian German differs from standard German in accent and vocabulary. "Grüß Gott" is the greeting; "Bitte" covers please, you\'re welcome, and here you are. "Jause" means a snack; "Erdapfel" is potato (not "Kartoffel"). English is widely spoken in Vienna — younger generations especially are fluent.', contextNote: 'Austrian menus use different terms: "Faschiertes" is minced meat; "Paradeiser" is tomato' },
    { topic: 'DRESS', title: 'Smart dress for opera and concerts', body: 'Vienna\'s musical culture (Staatsoper, Musikverein, Konzerthaus) has genuine dress expectations. Black tie is not required but smart dress (suit for men, cocktail dress or equivalent for women) is appropriate and common at the opera. Attending in jeans is technically permitted but conspicuous. Standing room tickets at the Staatsoper are formal too.', contextNote: 'Standing room (Stehplatz) at the Staatsoper costs €3–10 — extraordinary value for world-class opera' },
    { topic: 'SAFETY', title: 'Very safe, with few cautions', body: 'Vienna consistently ranks as one of the world\'s most liveable and safest cities. Violent crime targeting tourists is essentially non-existent. Pickpocketing is the primary concern at the Prater, Naschmarkt, and Stephansplatz. The U-Bahn is safe at all hours.', contextNote: 'Fake charity collectors with clipboards in the first district are persistent — politely decline' },
  ],

  'washington-dc-usa': [
    { topic: 'ETIQUETTE', title: 'Political awareness', body: 'Washington D.C. is a politically charged city — most residents have strong views shaped by working in or near government. Political conversations start quickly. You are free to engage but be measured; a city of policy professionals does not enjoy casual political generalisations. The city voted 92% Democratic in recent elections — context matters.', contextNote: 'Avoid discussing specific ongoing legislation unless you know the room' },
    { topic: 'FOOD', title: 'Half-smoke and Ethiopian food', body: 'D.C.\'s signature dish is the half-smoke (a smoked pork sausage between a hot dog and a bratwurst, served with chili and onions at Ben\'s Chili Bowl on U Street — Barack Obama\'s standing order). D.C. also has the US\'s largest Ethiopian diaspora; Adams Morgan and U Street have exceptional injera-and-stew restaurants.', contextNote: 'The National Mall has food trucks; surrounding neighbourhoods have far better restaurants' },
    { topic: 'TRANSPORT', title: 'Metro to every monument', body: 'The Washington Metro (WMATA) is clean and covers all major monuments and museums. Use a SmarTrip card or contactless payment. Fares vary by time and distance — rush hour is significantly more expensive. The Smithsonian station (Blue/Orange/Silver Line) drops you at the National Mall. Uber is expensive during rush hours.', contextNote: 'Never eat or drink on the Metro — it carries a $100 fine and is strictly enforced' },
    { topic: 'MONEY', title: 'Free museums are genuinely free', body: 'All 19 Smithsonian museums and galleries (National Air and Space, Natural History, American History, National Portrait Gallery, National Zoo) are free to enter — no booking fees, no "suggested donation" obligation. This is exceptional by global standards. Plan your museum days accordingly.', contextNote: 'The National Museum of African American History and Culture requires timed passes — book weeks in advance' },
    { topic: 'SAFETY', title: 'Ward disparities', body: 'D.C.\'s tourist zones (the National Mall, Georgetown, Dupont Circle, Capitol Hill) are well-patrolled and safe. Beyond those, the city has significant crime disparities by ward — particularly east of the Anacostia River. Use common urban sense; avoid walking alone in unfamiliar residential areas after midnight.', contextNote: 'The Capitol Hill neighbourhood near Union Station is safe; isolated parts of the Hill beyond Louisiana Ave require more awareness at night' },
    { topic: 'DRESS', title: 'Business casual dominates', body: 'Washington D.C. has a heavily business-focused dress culture — suits, blazers, and smart attire are worn more than in most US cities. Evenings in Georgetown and 14th Street NW are smart-casual. For the National Mall, comfortable walking shoes are essential — it stretches nearly 2 miles end to end.', contextNote: 'Congress members can be spotted in the Capitol Hill neighbourhood during session days' },
    { topic: 'LANGUAGE', title: 'Insider vocabulary', body: 'D.C. has its own political jargon that bleeds into daily speech: "the Hill" is Congress, "K Street" means lobbying, "inside the Beltway" means insular Washington thinking. Residents identify strongly by neighbourhood: "I\'m in Adams Morgan" vs. "I\'m in Foggy Bottom" signals different things about their life and politics.', contextNote: '"DMV" means DC/Maryland/Virginia — the regional shorthand, not the driver\'s licence office' },
  ],
};

async function main() {
  console.log('Starting culture seed...');
  await prisma.cultureEntry.deleteMany({});
  console.log('Cleared existing culture entries');

  let count = 0;
  for (const [slug, entries] of Object.entries(cultureData)) {
    const dest = await prisma.destination.findUnique({ where: { slug }, select: { id: true } });
    if (!dest) { console.warn(`Destination not found: ${slug}`); continue; }
    for (const entry of entries) {
      await prisma.cultureEntry.create({
        data: {
          destinationId: dest.id,
          topic: entry.topic,
          title: entry.title,
          body: entry.body,
          contextNote: entry.contextNote ?? null,
          sourceNote: 'TravelSphere editorial team',
        }
      });
      count++;
    }
    console.log(`Seeded ${entries.length} entries for ${slug}`);
  }
  console.log(`Total: ${count} culture entries seeded`);
  await prisma.$disconnect();
}

main().catch(e => { console.error(e); process.exit(1); });
